1	//! Xerj Console UX — embedded UI bundle served at `/_xerj-console`.
2	//!
3	//! `build.rs` walks the xerj-ux source tree at compile time and
4	//! generates `OUT_DIR/xerj_console_assets.rs` with a sorted slice of
5	//! `(url_path, bytes, content_type)` tuples. This module includes
6	//! that slice and exposes one Axum handler that does an O(log n)
7	//! lookup by path.
8	//!
9	//! ## URL shape
10	//!
11	//! ```text
12	//! GET /_xerj-console             → Console index.html (302 to /_xerj-console/)
13	//! GET /_xerj-console/            → Console index.html (200, text/html)
14	//! GET /_xerj-console/{path*}     → static asset by path, 404 if missing
15	//! GET /_xerj-console/share       → the share-link guest page (share/index.html)
16	//! ```
17	//!
18	//! Cache-Control is set to `public, max-age=300` for static assets;
19	//! the index.html gets `no-cache` so a deploy of a new binary surfaces
20	//! the new UI on next page load without ctrl-F5.
21	//!
22	//! ## Content-Security-Policy on the console page
23	//!
24	//! `index.html` is the page that shows other people's documents (the Reader)
25	//! and, in guest mode, holds a share's API key in `sessionStorage`. It is
26	//! served with [`CONSOLE_CSP`]: scripts from this origin only — no inline
27	//! script, no `eval` — and no connection to any other origin. The SPA builds
28	//! document-derived DOM without an HTML parser (`xerj-ux/src/ux/safe-dom.js`);
29	//! the policy is the second wall behind that one, so a missed escape in some
30	//! other view cannot become script execution or send a key off-origin.
31	//! `xerj-ux/test/browser/` loads the console under this exact string (it is
32	//! read out of this file) and fails on any violation report, so the policy
33	//! and the SPA cannot drift apart silently.
34	//!
35	//! `login.html` / `setup.html` carry an inline module script and show no
36	//! document data, so they are served without it.
37	//!
38	//! ## The share-link guest page
39	//!
40	//! `share/` is the one part of the bundle meant for someone who is **not** the
41	//! operator: the page a guest opens from a `xerj share` link, possibly through
42	//! a public tunnel. Like every other asset it is served without a session —
43	//! the guest has no credential until the page has exchanged a passcode for
44	//! one — so serving it makes nothing new reachable: it is three static files
45	//! that were already in the asset table. What it adds is a directory index
46	//! (`share` and `share/` both answer with `share/index.html`; the link the CLI
47	//! prints has no trailing slash) and a header set no other asset gets, see
48	//! [`GUEST_CSP`]. The page renders text from other people's documents, so the
49	//! policy is written to make a markup-injection bug inert rather than to rely
50	//! on there being none.
51	//!
52	//! ## Why not include_dir / rust-embed
53	//!
54	//! Both pull in proc-macro deps. The build.rs approach is ~80 LOC,
55	//! depends only on std, and produces a slice of `include_bytes!()`
56	//! references that the linker resolves directly.
57	
58	use axum::{
59	    extract::Path,
60	    http::{header, StatusCode},
61	    response::{IntoResponse, Redirect, Response},
62	};
63	
64	include!(concat!(env!("OUT_DIR"), "/xerj_console_assets.rs"));
65	
66	/// The policy `index.html` is served with. One line, no line breaks: the
67	/// browser tests parse it out of this file verbatim.
68	///
69	/// * `script-src 'self'` — no inline script, no `eval`, nothing off-origin.
70	/// * `connect-src 'self'` — `fetch` reaches this engine and nothing else.
71	/// * `style-src … 'unsafe-inline'` — the shell sets `style=""` attributes on
72	///   the markup it builds; styles cannot run script or read storage.
73	/// * fonts come from Google Fonts, as `index.html` has always linked them.
74	/// * `img-src data: blob:` — the inline favicon and the PNG chart export.
75	/// * `frame-ancestors 'none'` — the console cannot be framed (clickjacking).
76	pub const CONSOLE_CSP: &str = "default-src 'none'; script-src 'self'; connect-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; object-src 'none'";
77	
78	/// Find an asset by its url path. Linear scan is fine for ~50 files;
79	/// the slice is sorted so we could binary-search if the bundle grows.
80	fn find_asset(path: &str) -> Option<&'static (&'static str, &'static [u8], &'static str)> {
81	    XERJ_CONSOLE_ASSETS.iter().find(|(p, _, _)| *p == path)
82	}
83	
84	/// Everything under this asset directory is the share-link guest page.
85	const GUEST_DIR: &str = "share";
86	
87	/// The guest page's Content-Security-Policy.
88	///
89	/// `default-src 'none'` and then only what the page uses, all same-origin: its
90	/// one script, one stylesheet, one icon, and `fetch` back to this node. No
91	/// inline script or style is permitted — so text that somehow became markup
92	/// could not run — and no third-party origin is reachable, so nothing a guest
93	/// reads can be beaconed elsewhere. `form-action 'none'` matters for a
94	/// specific failure: the passcode form has no `action`, and if the script
95	/// failed to load a native submit would put the passcode in the query string
96	/// of a GET, i.e. in the address bar and the access log. `frame-ancestors
97	/// 'none'` (with `X-Frame-Options` for browsers that predate it) keeps the
98	/// passcode prompt out of anyone else's frame.
99	pub const GUEST_CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; \
100	     img-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; \
101	     frame-ancestors 'none'";
102	
103	/// Is `path` (an asset-table path) part of the guest page?
104	fn is_guest_asset(path: &str) -> bool {
105	    path.strip_prefix(GUEST_DIR)
106	        .is_some_and(|rest| rest.starts_with('/'))
107	}
108	
109	/// Map a request path onto the asset table: the guest page's directory index,
110	/// with or without the trailing slash. Everything else is served as asked.
111	fn resolve_request_path(rest: &str) -> &str {
112	    match rest {
113	        "share" | "share/" => "share/index.html",
114	        other => other,
115	    }
116	}
117	
118	/// Serve the Console's index.html for `/_xerj-console/`.
119	pub async fn xerj_console_index() -> impl IntoResponse {
120	    serve("index.html", true)
121	}
122	
123	/// Serve a named asset under `/_xerj-console/{path*}`.
124	pub async fn xerj_console_asset(Path(rest): Path<String>) -> impl IntoResponse {
125	    // Empty rest path = same as `/_xerj-console/` — serve index.
126	    let path = if rest.is_empty() {
127	        "index.html"
128	    } else {
129	        resolve_request_path(&rest)
130	    };
131	    serve(path, false)
132	}
133	
134	/// Bare `/_xerj-console` (no trailing slash) — relative `<script src="src/app.js">`
135	/// style tags resolve correctly only with the trailing slash, so redirect.
136	pub async fn xerj_console_redirect() -> impl IntoResponse {
137	    Redirect::permanent("/_xerj-console/")
138	}
139	
140	fn serve(path: &str, no_cache: bool) -> Response {
141	    // Defence-in-depth: no .. components allowed in a relative URL,
142	    // even though the asset table is statically built and cannot
143	    // contain them.
144	    if path.split('/').any(|seg| seg == ".." || seg.is_empty()) {
145	        return (StatusCode::BAD_REQUEST, "invalid path").into_response();
146	    }
147	    let asset = match find_asset(path) {
148	        Some(a) => a,
149	        None => {
150	            // Fall back to `<name>.html` when the path has no
151	            // extension — gives us nice URLs like `/_xerj-console/setup` and
152	            // `/_xerj-console/login` without an explicit `.html`. We never
153	            // append `.html` to a path with a dot already in the last
154	            // segment so a typo on a real asset still 404s instead of
155	            // serving the wrong page.
156	            if !path.rsplit('/').next().unwrap_or("").contains('.') {
157	                let html = format!("{path}.html");
158	                if let Some(a) = find_asset(&html) {
159	                    return serve_asset(a, no_cache);
160	                }
161	            }
162	            return (
163	                StatusCode::NOT_FOUND,
164	                format!("xerj-console asset not found: {path}"),
165	            )
166	                .into_response();
167	        }
168	    };
169	    serve_asset(asset, no_cache)
170	}
171	
172	fn serve_asset(asset: &(&'static str, &'static [u8], &'static str), no_cache: bool) -> Response {
173	    if is_guest_asset(asset.0) {
174	        return serve_guest_asset(asset);
175	    }
176	    // The console page is always revalidated — also when it is requested by
177	    // name (`/_xerj-console/index.html`) rather than as the directory index —
178	    // so a new binary's UI and policy arrive together.
179	    let is_console_page = asset.0 == "index.html";
180	    let cache = if no_cache || is_console_page {
181	        "no-cache"
182	    } else {
183	        "public, max-age=300"
184	    };
185	    let mut resp = (
186	        [
187	            (header::CONTENT_TYPE, asset.2),
188	            (header::CACHE_CONTROL, cache),
189	            // Every asset declares its real type (build.rs); never let a
190	            // browser second-guess it.
191	            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
192	        ],
193	        asset.1,
194	    )
195	        .into_response();
196	    if is_console_page {
197	        let h = resp.headers_mut();
198	        h.insert(
199	            header::CONTENT_SECURITY_POLICY,
200	            header::HeaderValue::from_static(CONSOLE_CSP),
201	        );
202	        // A guest's tab holds a key; never send this page's URL anywhere.
203	        h.insert(
204	            header::REFERRER_POLICY,
205	            header::HeaderValue::from_static("no-referrer"),
206	        );
207	    }
208	    resp
209	}
210	
211	/// The guest page and its assets: never stored, never framed, never sniffed,
212	/// never a `Referer` source, and confined by [`GUEST_CSP`].
213	///
214	/// `no-store` rather than the console's five-minute cache: a guest may be on
215	/// a borrowed or shared browser, and a page fetched through a quick tunnel
216	/// must not be replayed from a cache after the tunnel — and its hostname — is
217	/// gone. The files are a few kilobytes; the cost is nothing.
218	fn serve_guest_asset(asset: &(&'static str, &'static [u8], &'static str)) -> Response {
219	    (
220	        [
221	            (header::CONTENT_TYPE, asset.2),
222	            (header::CACHE_CONTROL, "no-store, max-age=0"),
223	            (header::PRAGMA, "no-cache"),
224	            (header::CONTENT_SECURITY_POLICY, GUEST_CSP),
225	            (header::REFERRER_POLICY, "no-referrer"),
226	            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
227	            (header::X_FRAME_OPTIONS, "DENY"),
228	            (
229	                header::HeaderName::from_static("cross-origin-opener-policy"),
230	                "same-origin",
231	            ),
232	            (
233	                header::HeaderName::from_static("cross-origin-resource-policy"),
234	                "same-origin",
235	            ),
236	            (
237	                header::HeaderName::from_static("permissions-policy"),
238	                "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
239	            ),
240	            (
241	                header::HeaderName::from_static("x-robots-tag"),
242	                "noindex, nofollow, noarchive",
243	            ),
244	        ],
245	        asset.1,
246	    )
247	        .into_response()
248	}
249	
250	/// Number of bundled assets — exposed for the startup banner so
251	/// operators see at-a-glance whether the Console UX was bundled.
252	pub fn asset_count() -> usize {
253	    XERJ_CONSOLE_ASSETS.len()
254	}
255	
256	#[cfg(test)]
257	mod tests {
258	    use super::*;
259	
260	    /// A release tarball may omit `xerj-ux/` (build.rs then emits an empty
261	    /// table). With nothing bundled there is nothing to assert about.
262	    fn bundled() -> bool {
263	        asset_count() > 0
264	    }
265	
266	    fn asset_text(path: &str) -> String {
267	        let asset = find_asset(path).unwrap_or_else(|| panic!("{path} is not bundled"));
268	        String::from_utf8(asset.1.to_vec()).expect("utf-8 asset")
269	    }
270	
271	    fn header<'a>(resp: &'a Response, name: &str) -> &'a str {
272	        resp.headers()
273	            .get(name)
274	            .unwrap_or_else(|| panic!("missing header {name}"))
275	            .to_str()
276	            .unwrap()
277	    }
278	
279	    /// Drop `/* … */` blocks and whole-line `//` comments, so a scan for a
280	    /// forbidden API does not trip over the comment that forbids it.
281	    fn strip_js_comments(src: &str) -> String {
282	        let mut out = String::with_capacity(src.len());
283	        let mut rest = src;
284	        while let Some(start) = rest.find("/*") {
285	            out.push_str(&rest[..start]);
286	            match rest[start..].find("*/") {
287	                Some(end) => rest = &rest[start + end + 2..],
288	                None => {
289	                    rest = "";
290	                    break;
291	                }
292	            }
293	        }
294	        out.push_str(rest);
295	        out.lines()
296	            .filter(|l| !l.trim_start().starts_with("//"))
297	            .collect::<Vec<_>>()
298	            .join("\n")
299	    }
300	
301	    #[test]
302	    fn the_guest_page_answers_with_and_without_the_trailing_slash() {
303	        if !bundled() {
304	            return;
305	        }
306	        // The CLI prints `/_xerj-console/share#<id>`; a mail client or a
307	        // person may add the slash. Both are the page, not a 404 or a 400.
308	        for rest in ["share", "share/", "share/index.html"] {
309	            let resp = serve(resolve_request_path(rest), false);
310	            assert_eq!(resp.status(), StatusCode::OK, "{rest}");
311	            assert_eq!(header(&resp, "content-type"), "text/html; charset=utf-8");
312	            assert_eq!(header(&resp, "content-security-policy"), GUEST_CSP);
313	        }
314	    }
315	
316	    #[test]
317	    fn guest_assets_carry_the_strict_header_set() {
318	        if !bundled() {
319	            return;
320	        }
321	        for path in ["share/index.html", "share/share.js", "share/share.css"] {
322	            let resp = serve(path, false);
323	            assert_eq!(resp.status(), StatusCode::OK, "{path}");
324	            assert_eq!(header(&resp, "cache-control"), "no-store, max-age=0");
325	            assert_eq!(header(&resp, "referrer-policy"), "no-referrer");
326	            assert_eq!(header(&resp, "x-content-type-options"), "nosniff");
327	            assert_eq!(header(&resp, "x-frame-options"), "DENY");
328	            assert_eq!(header(&resp, "cross-origin-opener-policy"), "same-origin");
329	            let csp = header(&resp, "content-security-policy");
330	            for directive in [
331	                "default-src 'none'",
332	                "script-src 'self'",
333	                "style-src 'self'",
334	                "connect-src 'self'",
335	                "base-uri 'none'",
336	                "form-action 'none'",
337	                "frame-ancestors 'none'",
338	            ] {
339	                assert!(csp.contains(directive), "{path}: CSP lacks {directive}");
340	            }
341	            // Nothing that would let injected markup run or phone home.
342	            for forbidden in [
343	                "unsafe-inline",
344	                "unsafe-eval",
345	                "data:",
346	                "blob:",
347	                "*",
348	                "http",
349	            ] {
350	                assert!(!csp.contains(forbidden), "{path}: CSP contains {forbidden}");
351	            }
352	        }
353	    }
354	
355	    /// The share work (#947) asserted the console page carried NO
356	    /// Content-Security-Policy, which was true when only `share/` had one.
357	    /// The Reader (#945) gives the console page its own [`CONSOLE_CSP`] — it
358	    /// renders other people's documents and, in guest mode, holds a share key
359	    /// in `sessionStorage`. So the console is deliberately no longer served
360	    /// "exactly as before"; what must still hold is that it gets the CONSOLE
361	    /// policy and not the guest one, and that no console asset is mistaken
362	    /// for a guest asset.
363	    #[test]
364	    fn the_console_page_carries_the_console_policy_not_the_guest_one() {
365	        if !bundled() {
366	            return;
367	        }
368	        let resp = serve("index.html", true);
369	        assert_eq!(resp.status(), StatusCode::OK);
370	        assert_eq!(header(&resp, "cache-control"), "no-cache");
371	        assert_eq!(header(&resp, "content-security-policy"), CONSOLE_CSP);
372	        assert_ne!(header(&resp, "content-security-policy"), GUEST_CSP);
373	        assert!(!is_guest_asset("index.html"));
374	        assert!(!is_guest_asset("shared.js"));
375	        assert!(!is_guest_asset("share"));
376	        assert!(is_guest_asset("share/share.js"));
377	    }
378	
379	    #[test]
380	    fn the_directory_index_opens_nothing_else() {
381	        // Only the two spellings of the directory map anywhere.
382	        assert_eq!(resolve_request_path("share"), "share/index.html");
383	        assert_eq!(resolve_request_path("share/"), "share/index.html");
384	        for other in [
385	            "shared",
386	            "share/x",
387	            "share//",
388	            "api/v1/me",
389	            "src/",
390	            "share/..",
391	        ] {
392	            assert_eq!(resolve_request_path(other), other);
393	        }
394	        for bad in [
395	            "share/..",
396	            "share/../index.html",
397	            "share//share.js",
398	            "../share",
399	        ] {
400	            assert_eq!(serve(bad, false).status(), StatusCode::BAD_REQUEST, "{bad}");
401	        }
402	        for missing in ["share/nope.js", "shared", "share/share", "share/index.htm"] {
403	            assert_eq!(
404	                serve(missing, false).status(),
405	                StatusCode::NOT_FOUND,
406	                "{missing}"
407	            );
408	        }
409	        // The console's extensionless fallback (`setup` → `setup.html`) also
410	        // makes `share/index` the page. It is the same file, and it gets the
411	        // same policy — the guest header set is keyed on the asset served,
412	        // not on the spelling of the request.
413	        if bundled() {
414	            let resp = serve("share/index", false);
415	            assert_eq!(resp.status(), StatusCode::OK);
416	            assert_eq!(header(&resp, "content-security-policy"), GUEST_CSP);
417	        }
418	    }
419	
420	    #[test]
421	    fn the_guest_page_has_no_inline_code_and_loads_nothing_from_elsewhere() {
422	        if !bundled() {
423	            return;
424	        }
425	        let html = asset_text("share/index.html");
426	        let lower = html.to_ascii_lowercase();
427	        // Every <script> is external; the CSP would refuse an inline one, and
428	        // this fails the build before a browser has to.
429	        for (at, _) in lower.match_indices("<script") {
430	            let tag_end = lower[at..].find('>').map(|e| at + e).unwrap_or(lower.len());
431	            assert!(
432	                lower[at..tag_end].contains("src="),
433	                "inline <script> at byte {at}"
434	            );
435	        }
436	        // (`javascript:` is matched as an attribute value: the <noscript> text
437	        // legitimately says "This page needs JavaScript: …".)
438	        for forbidden in [
439	            "<style",
440	            " style=",
441	            "=\"javascript:",
442	            "='javascript:",
443	            "=javascript:",
444	            "http://",
445	            "https://",
446	            "src=\"//",
447	            "href=\"//",
448	            "<iframe",
449	            "<object",
450	            "<embed",
451	            "<base",
452	        ] {
453	            assert!(
454	                !lower.contains(forbidden),
455	                "guest page contains {forbidden}"
456	            );
457	        }
458	        // No inline event handlers (` onclick=`, ` onerror=`, …).
459	        for (at, _) in lower.match_indices(" on") {
460	            let word: String = lower[at + 1..]
461	                .chars()
462	                .take_while(|c| c.is_ascii_alphabetic())
463	                .collect();
464	            let after = lower[at + 1 + word.len()..].chars().next();
465	            assert!(
466	                after != Some('='),
467	                "inline event handler `{word}=` in the guest page"
468	            );
469	        }
470	        // What the page tells a guest has to be true through a tunnel too
471	        // (review of PR #947): it used to say the browser "talks to their
472	        // machine" and that nothing goes "to a third party", on a page served
473	        // through Cloudflare. The Cloudflare notice ships hidden; share.js
474	        // shows it on a quick-tunnel hostname.
475	        for untrue in ["third party", "talks to their machine"] {
476	            assert!(!lower.contains(untrue), "guest page still says `{untrue}`");
477	        }
478	        for id in ["id=\"via-tunnel\" hidden", "id=\"room-via-tunnel\" hidden"] {
479	            assert!(html.contains(id), "guest page lacks {id}");
480	        }
481	        assert!(lower.contains("cloudflare carries the connection and can read"));
482	        // Every asset it names is one the bundle actually carries.
483	        for asset in ["share/share.js", "share/share.css", "share/icon.svg"] {
484	            assert!(find_asset(asset).is_some(), "{asset} is not bundled");
485	            assert!(
486	                html.contains(&format!("/_xerj-console/{asset}")),
487	                "page does not reference {asset}"
488	            );
489	        }
490	    }
491	
492	    #[test]
493	    fn the_guest_script_never_parses_document_text_as_markup() {
494	        if !bundled() {
495	            return;
496	        }
497	        // Text from the shared index is attacker-controlled (it is other
498	        // people's email). The page may only ever place it as text.
499	        let code = strip_js_comments(&asset_text("share/share.js"));
500	        for sink in [
501	            "innerHTML",
502	            "outerHTML",
503	            "insertAdjacentHTML",
504	            "document.write",
505	            "DOMParser",
506	            "createContextualFragment",
507	            "srcdoc",
508	            "eval(",
509	            "new Function",
510	            "setTimeout('",
511	            "setTimeout(\"",
512	            "localStorage",
513	            "document.cookie",
514	        ] {
515	            assert!(!code.contains(sink), "share.js uses `{sink}`");
516	        }
517	        // The one storage contract the console's guest mode depends on.
518	        assert!(code.contains("'xerj.share'"));
519	        assert!(code.contains("sessionStorage.setItem(SHARE_KEY"));
520	        // The share id goes to the node in the claim BODY. A path built from
521	        // it is what put the id into access logs (review of PR #947).
522	        assert!(code.contains("'/_share/claim'"), "claim route");
523	        assert!(
524	            !code.contains("/_share/${"),
525	            "share.js builds a /_share path from a variable — the id must stay out of URLs"
526	        );
527	        assert!(code.contains("{ id: state.shareId, passcode }"));
528	        // A link pasted over another differs only in its fragment.
529	        assert!(code.contains("'hashchange'"));
530	        // The highlight delimiters are private-use code points, which are
531	        // invisible in an editor and in review: they must be written as
532	        // escapes, never as the characters themselves.
533	        assert!(
534	            !asset_text("share/share.js")
535	                .chars()
536	                .any(|c| ('\u{E000}'..='\u{F8FF}').contains(&c)),
537	            "share.js contains a raw private-use character; write it as \\uE000"
538	        );
539	        assert!(code.contains("'\\uE000'") && code.contains("'\\uE001'"));
540	        // No request leaves the origin: every fetch target is a path.
541	        assert!(!code.contains("http://") && !code.contains("https://"));
542	    }
543	}
