1	//! Who the caller *is*, as opposed to who they claim to be (#76 S5-4).
2	//!
3	//! Every auth endpoint charges a per-IP rate-limit bucket and stamps a source
4	//! address into the audit log. Both used to be derived from `X-Forwarded-For`
5	//! — a header the caller writes. A rotating `x-forwarded-for: 1.2.3.$RANDOM`
6	//! therefore got a fresh quota on every request (unthrottled brute force of
7	//! magic links and the bootstrap claim) while honest clients, who send no such
8	//! header, stayed throttled. Exactly backwards.
9	//!
10	//! The address now comes from the transport: [`axum::extract::ConnectInfo`],
11	//! i.e. the TCP peer, which the caller cannot forge.
12	//!
13	//! ## Reverse proxies
14	//!
15	//! Behind a legitimate proxy the peer *is* the proxy, and keying purely on the
16	//! socket would collapse every user into one bucket — a self-inflicted DoS. So
17	//! forwarding headers are honoured, but only when the socket peer is a proxy
18	//! the operator declared in `server.trusted_proxies`. The list is empty by
19	//! default: **an unconfigured node believes nobody**.
20	//!
21	//! ## Reading the chain
22	//!
23	//! `X-Forwarded-For` is a comma-separated chain, appended to left-to-right.
24	//! The left end is whatever the original caller sent — attacker-controlled.
25	//! The *right-most* entry is the one your own outermost proxy just wrote, so
26	//! the chain is walked right-to-left, skipping entries that are themselves
27	//! declared proxies, and the first non-proxy address wins. A malformed
28	//! element stops the walk (we do not step over it into attacker-authored
29	//! text) and we fall back to the peer.
30	
31	use std::net::{IpAddr, SocketAddr};
32	
33	use axum::{
34	    async_trait,
35	    extract::{ConnectInfo, FromRequestParts},
36	    http::{request::Parts, HeaderMap},
37	};
38	use xerj_common::net::{canonical_ip, parse_forwarded_element, TrustedProxies};
39	
40	/// The bucket key used when we cannot establish any address at all (no
41	/// `ConnectInfo` in the request extensions — e.g. a router driven directly by
42	/// `tower::ServiceExt::oneshot` in a test, or a future transport that does not
43	/// carry a peer). Failing to one shared bucket throttles rather than
44	/// exempts: strictly safer than believing a header.
45	pub const UNKNOWN_IP: &str = "unknown";
46	
47	/// Resolve the caller's address.
48	///
49	/// `peer` is the real socket peer. Returns the address as a string because
50	/// that is what the rate-limit key and the audit record want; the value is
51	/// always either a canonical IP literal or [`UNKNOWN_IP`], never
52	/// caller-authored text.
53	pub fn resolve(peer: Option<IpAddr>, headers: &HeaderMap, trusted: &TrustedProxies) -> String {
54	    let Some(peer) = peer.map(canonical_ip) else {
55	        // No transport identity. Header data cannot rescue this — it would
56	        // reintroduce the very spoof we are closing.
57	        return UNKNOWN_IP.to_string();
58	    };
59	
60	    // The common case, and the whole point: an ordinary client's headers are
61	    // never consulted.
62	    if !trusted.contains(&peer) {
63	        return peer.to_string();
64	    }
65	
66	    // Peer is a declared proxy — its forwarding headers may be believed.
67	    // Multiple `X-Forwarded-For` headers are equivalent to one comma-joined
68	    // header (RFC 7230 §3.2.2), so walk every value, right-to-left.
69	    let elements: Vec<&str> = headers
70	        .get_all("x-forwarded-for")
71	        .iter()
72	        .filter_map(|v| v.to_str().ok())
73	        .flat_map(|v| v.split(','))
74	        .collect();
75	
76	    if !elements.is_empty() {
77	        for element in elements.iter().rev() {
78	            match parse_forwarded_element(element) {
79	                Some(ip) => {
80	                    let ip = canonical_ip(ip);
81	                    if !trusted.contains(&ip) {
82	                        return ip.to_string();
83	                    }
84	                    // Another of our own proxies — keep walking left.
85	                }
86	                // Garbage or an obfuscated identifier. Stop: anything further
87	                // left is behind text we could not validate.
88	                None => return peer.to_string(),
89	            }
90	        }
91	        // Every hop in the chain was one of our own proxies; the original
92	        // client was never recorded.
93	        return peer.to_string();
94	    }
95	
96	    // No forwarded chain — honour the single-valued `X-Real-IP` that nginx
97	    // and friends set. Same trust gate: only because the peer is declared.
98	    if let Some(ip) = headers
99	        .get("x-real-ip")
100	        .and_then(|v| v.to_str().ok())
101	        .and_then(parse_forwarded_element)
102	    {
103	        return canonical_ip(ip).to_string();
104	    }
105	
106	    peer.to_string()
107	}
108	
109	/// Extractor form: the caller's address, already trust-resolved.
110	///
111	/// Use this in handlers instead of reading headers. It needs `ConnectInfo` in
112	/// the request extensions, which the server installs via
113	/// `into_make_service_with_connect_info::<SocketAddr>()` on both the plain and
114	/// the TLS listener.
115	#[derive(Debug, Clone)]
116	pub struct ClientIp(pub String);
117	
118	impl ClientIp {
119	    pub fn as_str(&self) -> &str {
120	        &self.0
121	    }
122	}
123	
124	#[async_trait]
125	impl<S> FromRequestParts<S> for ClientIp
126	where
127	    S: TrustedProxySource + Send + Sync,
128	{
129	    type Rejection = std::convert::Infallible;
130	
131	    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
132	        let peer = parts
133	            .extensions
134	            .get::<ConnectInfo<SocketAddr>>()
135	            .map(|ci| ci.0.ip());
136	        Ok(ClientIp(resolve(
137	            peer,
138	            &parts.headers,
139	            state.trusted_proxies(),
140	        )))
141	    }
142	}
143	
144	/// State that can say which proxies are trusted. Implemented by
145	/// `ConsoleState`; a trait so the extractor stays testable without one.
146	pub trait TrustedProxySource {
147	    fn trusted_proxies(&self) -> &TrustedProxies;
148	}
