47	pub async fn list(
48	    State(state): State<ConsoleState>,
49	    sess: AuthSession,
50	    Query(q): Query<ListQuery>,
51	) -> ConsoleResult<Response> {
52	    let idx = state.engine.get_index(indices::VIEWS)?;
53	    let mut must: Vec<Value> = vec![json!({ "term": { "owner": sess.user.id } })];
54	    if let Some(dash) = q.dashboard {
55	        must.push(json!({ "term": { "dashboard_id": dash } }));
56	    }
57	    let body = json!({
