60	    });
61	    let req = xerj_query::parser::parse_request(&body)
62	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
63	    let r = idx.search(&req).await?;
64	    let items: Vec<Value> = r.hits.into_iter().map(|h| h.source).collect();
65	    Ok(ok(json!({ "views": items, "total": items.len() }), None))
