78	pub async fn create(
79	    State(state): State<ConsoleState>,
80	    sess: AuthSession,
81	    Json(body): Json<CreateBody>,
82	) -> ConsoleResult<Response> {
83	    let id = uuid::Uuid::new_v4().to_string();
84	    let view = View {
85	        id: id.clone(),
86	        owner: sess.user.id.clone(),
87	        org_id: default_org(),
88	        dashboard_id: body.dashboard_id,
89	        name: body.name,
90	        time: body.time,
91	        filters: body.filters,
92	        updated_at: now_iso(),
93	    };
94	    let idx = state.engine.get_index(indices::VIEWS)?;
95	    idx.create_document(id.clone(), serde_json::to_value(&view)?)
96	        .await?;
97	    let location = format!("/_xerj-console/api/v1/views/{id}");
98	    Ok(created(view, &location, None))
99	}
100	
101	pub async fn get_one(
102	    State(state): State<ConsoleState>,
103	    sess: AuthSession,
104	    Path(id): Path<String>,
105	) -> ConsoleResult<Response> {
106	    let view = read(&state, &id).await?;
107	    if view.owner != sess.user.id {
108	        return Err(ConsoleApiError::NotFound("view".into()));
109	    }
110	    Ok(ok(view, None))
111	}
112	
113	pub async fn delete(
114	    State(state): State<ConsoleState>,
115	    sess: AuthSession,
116	    Path(id): Path<String>,
117	) -> ConsoleResult<Response> {
118	    let view = read(&state, &id).await?;
119	    if view.owner != sess.user.id {
120	        return Err(ConsoleApiError::NotFound("view".into()));
121	    }
122	    let idx = state.engine.get_index(indices::VIEWS)?;
123	    // Same contract as `store::delete_passkey`: `Ok(false)` is already-absent
124	    // (idempotent), so only a refused write becomes an error. Swallowing
125	    // that error used to return 204 while the view stayed on disk.
126	    idx.delete_document(&id).await?;
127	    Ok(no_content())
128	}
129	
130	async fn read(state: &ConsoleState, id: &str) -> ConsoleResult<View> {
131	    let idx = state.engine.get_index(indices::VIEWS)?;
132	    let body = json!({
133	        "query": { "ids": { "values": [id] } },
134	        "size": 1
135	    });
136	    let req = xerj_query::parser::parse_request(&body)
137	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
138	    let r = idx.search(&req).await?;
139	    let hit = r
140	        .hits
141	        .into_iter()
142	        .next()
143	        .ok_or_else(|| ConsoleApiError::NotFound(format!("view {id}")))?;
144	    Ok(serde_json::from_value(hit.source)?)
145	}
