1	//! Per-user UI preferences — `GET /prefs` and `PUT /prefs`.
2	//!
3	//! Replaces every `localStorage["xerj.*"]` write the Console UX does
4	//! today: theme, default cluster, time range, mobile flag, search-box
5	//! contents.  We don't constrain the schema — the doc is whatever
6	//! key/value pairs the SPA asks us to round-trip — but `_id` is always
7	//! the user_id, so reads are by-id and idempotent.
8	
9	use axum::{extract::State, response::Response, Json};
10	use serde_json::{json, Value};
11	
12	use crate::auth::sessions::AuthSession;
13	use crate::error::{ConsoleApiError, ConsoleResult};
14	use crate::indices;
15	use crate::response::ok;
16	use crate::state::ConsoleState;
17	use crate::time::now_iso;
18	
19	const FALLBACK_PREFS: &str = r#"{
20	  "theme": "dark",
21	  "time": "24H",
22	  "cluster": "LOCAL",
23	  "mobile": false
24	}"#;
25	
26	pub async fn get(State(state): State<ConsoleState>, sess: AuthSession) -> ConsoleResult<Response> {
27	    let idx = state.engine.get_index(indices::PREFS)?;
28	    let body = json!({
29	        "query": { "ids": { "values": [&sess.user.id] } },
30	        "size": 1
31	    });
32	    let req = xerj_query::parser::parse_request(&body)
33	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
34	    let r = idx.search(&req).await?;
35	    let prefs = match r.hits.into_iter().next() {
36	        Some(h) => h.source,
37	        None => serde_json::from_str(FALLBACK_PREFS).expect("fallback prefs are valid json"),
38	    };
39	    Ok(ok(prefs, None))
40	}
41	
42	pub async fn put(
43	    State(state): State<ConsoleState>,
44	    sess: AuthSession,
45	    Json(mut body): Json<Value>,
46	) -> ConsoleResult<Response> {
47	    if !body.is_object() {
48	        return Err(ConsoleApiError::BadRequest(
49	            "prefs body must be a JSON object".into(),
50	        ));
51	    }
52	    // Strip any client-set "updated_at" so the server is authoritative.
53	    body.as_object_mut()
54	        .unwrap()
55	        .insert("updated_at".into(), Value::String(now_iso()));
56	
57	    let idx = state.engine.get_index(indices::PREFS)?;
58	    // One in-place upsert. delete-then-create used to drop the live prefs
59	    // row when the replacement write was refused.
60	    idx.index_document(Some(sess.user.id.clone()), body.clone())
61	        .await?;
62	    Ok(ok(body, None))
63	}
