1	//! Cookie-backed sessions.
2	//!
3	//! After a successful passkey assertion (enrollment-finish or login-finish)
4	//! the server mints a session id, persists a `.xerj_sessions` doc, and
5	//! returns a `Set-Cookie: xerj_session=<id>.<sig>` header. The signature
6	//! is HMAC-SHA256 of the session id keyed by `ConsoleState.master_key`.
7	//!
8	//! Cookie attributes:
9	//! - `HttpOnly`: blocks JS from reading the cookie (mitigates XSS theft).
10	//! - `Secure`: not set on http/localhost (so dev works) — set on https
11	//!   when the request was over TLS.
12	//! - `SameSite=Lax`: protects against cross-site POST CSRF; `Lax` (not
13	//!   `Strict`) lets the SPA bookmark links work cross-origin top-nav.
14	//! - `Path=/_xerj-console`: scoped tightly so xerj's other surfaces never see
15	//!   the cookie even when proxied alongside.
16	//!
17	//! Idle expiry: a session is considered fresh if `now < expires_at AND
18	//! now < last_seen_at + idle_seconds`. `last_seen_at` is bumped on
19	//! every authenticated request via the extractor.
20	
21	use axum::{
22	    extract::FromRequestParts,
23	    http::{request::Parts, HeaderValue, StatusCode},
24	};
25	use axum_extra::extract::cookie::{Cookie, CookieJar, SameSite};
26	use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
27	use hmac::{Hmac, Mac};
28	use rand::RngCore;
29	use sha2::Sha256;
30	use subtle::ConstantTimeEq;
31	
32	use crate::auth::store;
33	use crate::bootstrap::sha256_hex;
34	use crate::error::{ConsoleApiError, ConsoleResult};
35	use crate::state::ConsoleState;
36	use crate::time::{epoch_ms_to_iso, now_epoch_ms, now_iso, parse_iso};
37	use xerj_engine::Engine;
38	
39	type HmacSha256 = Hmac<Sha256>;
40	
41	pub const COOKIE_NAME: &str = "xerj_session";
42	pub const SESSION_TTL_MS: i64 = 12 * 60 * 60 * 1000; // 12 hours hard expiry
43	pub const SESSION_IDLE_MS: i64 = 30 * 60 * 1000; //  30 minutes idle
44	
45	// ─────────────────────────────────────────────────────────────────────────────
46	// Mint
47	// ─────────────────────────────────────────────────────────────────────────────
48	
49	/// Create a fresh session for `user_id`, persist it, and return both the
50	/// row and the cookie value the SPA should echo back.
51	pub async fn mint_session(
52	    state: &ConsoleState,
53	    user_id: &str,
54	    idp: &str,
55	    ip: Option<String>,
56	    ua: Option<String>,
57	) -> ConsoleResult<(store::Session, String)> {
58	    let mut id_bytes = [0u8; 32];
59	    rand::thread_rng().fill_bytes(&mut id_bytes);
60	    let session_id = URL_SAFE_NO_PAD.encode(id_bytes);
61	
62	    let now_ms = now_epoch_ms();
63	    let now_iso_s = now_iso();
64	    let session = store::Session {
65	        id: session_id.clone(),
66	        user_id: user_id.to_string(),
67	        created_at: now_iso_s.clone(),
68	        expires_at: epoch_ms_to_iso(now_ms + SESSION_TTL_MS),
69	        last_seen_at: now_iso_s,
70	        ip,
71	        ua,
72	        idp: idp.to_string(),
73	        revoked_at: None,
74	    };
75	    store::put_session(&state.engine, &session).await?;
76	
77	    let signed = sign_session_id(&session_id, &state.master_key);
78	    Ok((session, signed))
79	}
80	
81	/// Sign `session_id` with the master key. Output is `<id>.<sig_b64u>`.
82	pub fn sign_session_id(session_id: &str, master_key: &[u8; 32]) -> String {
83	    let mut mac = HmacSha256::new_from_slice(master_key).expect("hmac key");
84	    mac.update(session_id.as_bytes());
85	    let sig = URL_SAFE_NO_PAD.encode(mac.finalize().into_bytes());
86	    format!("{session_id}.{sig}")
87	}
88	
89	/// Verify and split a `<id>.<sig>` cookie. Constant-time comparison.
90	pub fn verify_session_cookie(value: &str, master_key: &[u8; 32]) -> Option<String> {
91	    let (id, sig) = value.split_once('.')?;
92	    let expected = sign_session_id(id, master_key);
93	    let (_id_part, expected_sig) = expected.rsplit_once('.')?;
94	    if expected_sig.as_bytes().ct_eq(sig.as_bytes()).into() {
95	        Some(id.to_string())
96	    } else {
97	        None
98	    }
99	}
