125	/// Authenticated session, extracted from the `xerj_session` cookie.
126	///
127	/// Use as a handler parameter to require authentication. Returns 401 on
128	/// missing cookie, bad signature, expired session, or revoked session.
129	#[derive(Debug, Clone)]
130	pub struct AuthSession {
131	    pub session_id: String,
132	    pub user: store::User,
133	}
134	
135	#[axum::async_trait]
136	impl FromRequestParts<ConsoleState> for AuthSession {
137	    type Rejection = ConsoleApiError;
138	
139	    async fn from_request_parts(
140	        parts: &mut Parts,
141	        state: &ConsoleState,
142	    ) -> Result<Self, Self::Rejection> {
143	        // API clients authenticate with `Authorization: Bearer <token>`;
144	        // browsers with a signed session cookie. Bearer wins when present so
145	        // a token-carrying request is never silently downgraded to the
146	        // (absent) cookie path.
147	        if let Some(token) = bearer_token(&parts.headers) {
148	            return authenticate_bearer(state, &token).await;
149	        }
150	
151	        let jar = CookieJar::from_headers(&parts.headers);
152	        let cookie = jar
153	            .get(COOKIE_NAME)
154	            .ok_or_else(|| ConsoleApiError::Unauthorized("no session".into()))?;
155	        let session_id = verify_session_cookie(cookie.value(), &state.master_key)
156	            .ok_or_else(|| ConsoleApiError::Unauthorized("bad session signature".into()))?;
157	
158	        let session = store::get_session(&state.engine, &session_id)
159	            .await?
160	            .ok_or_else(|| ConsoleApiError::Unauthorized("unknown session".into()))?;
161	
162	        if session.revoked_at.is_some() {
163	            return Err(ConsoleApiError::Unauthorized("session revoked".into()));
164	        }
165	        let now_ms = now_epoch_ms();
166	        if let Some(exp) = parse_iso(&session.expires_at) {
167	            if now_ms > exp.timestamp_millis() {
168	                return Err(ConsoleApiError::Unauthorized("session expired".into()));
169	            }
170	        }
171	        if let Some(seen) = parse_iso(&session.last_seen_at) {
172	            if now_ms - seen.timestamp_millis() > SESSION_IDLE_MS {
173	                return Err(ConsoleApiError::Unauthorized("session idle".into()));
174	            }
175	        }
176	
177	        let user = store::get_user(&state.engine, &session.user_id)
178	            .await?
179	            .ok_or_else(|| ConsoleApiError::Unauthorized("session user gone".into()))?;
180	        if user.status != store::UserStatus::Active {
181	            return Err(ConsoleApiError::Unauthorized("user disabled".into()));
182	        }
183	
184	        // Bump last_seen so the session stays fresh while the user is active.
185	        // Best-effort — we don't fail the request if the write races with another
186	        // tab. SECURITY (S5-1): do NOT blind-write the session we read at the top
187	        // of this function. A concurrent revoke_session() between that read and
188	        // this write would be clobbered by the stale copy (revoked_at: None),
189	        // resurrecting a revoked session — a revocation bypass. Re-read and bump
190	        // only the fresh record, skipping entirely if it is now revoked or gone.
191	        bump_last_seen(&state.engine, &session_id).await;
192	
193	        Ok(AuthSession { session_id, user })
194	    }
195	}
196	
197	// ─────────────────────────────────────────────────────────────────────────────
198	// Bearer (API token) authentication
199	// ─────────────────────────────────────────────────────────────────────────────
200	
201	/// Refresh a session's `last_seen_at` without clobbering a concurrent revocation.
202	///
203	/// S5-1 fix: re-reads the session immediately before writing and skips the write
204	/// if it is now gone or revoked, so a `revoke_session()` that landed after the
205	/// request's initial auth read cannot be overwritten by a stale copy. The write
206	/// carries the *fresh* record's fields (including its `revoked_at`), so even the
207	/// tiny residual window between this re-read and the put cannot resurrect a
208	/// revoked session — it would only rewrite an already-revoked record unchanged.
209	/// Best-effort: any store error is swallowed, exactly as before.
210	pub(crate) async fn bump_last_seen(engine: &Engine, session_id: &str) {
211	    let fresh = match store::get_session(engine, session_id).await {
212	        Ok(Some(s)) => s,
213	        _ => return, // gone (revoked-by-delete or expired-out) → do not recreate
214	    };
215	    if fresh.revoked_at.is_some() {
216	        return; // revoked between auth read and now → must not refresh
217	    }
218	    let mut bumped = fresh;
219	    bumped.last_seen_at = now_iso();
220	    let _ = store::put_session(engine, &bumped).await;
221	}
222	
223	/// Pull the secret out of an `Authorization: Bearer <secret>` header.
224	/// Returns `None` when the header is absent, is not a bearer scheme, or
225	/// carries an empty value — the caller then falls back to the cookie path.
226	fn bearer_token(headers: &axum::http::HeaderMap) -> Option<String> {
227	    let raw = headers
228	        .get(axum::http::header::AUTHORIZATION)?
229	        .to_str()
230	        .ok()?;
231	    let rest = raw
232	        .strip_prefix("Bearer ")
233	        .or_else(|| raw.strip_prefix("bearer "))?;
234	    let trimmed = rest.trim();
235	    if trimmed.is_empty() {
236	        None
237	    } else {
238	        Some(trimmed.to_string())
239	    }
240	}
241	
242	/// Authenticate a presented API token: hash it, look up a non-revoked
243	/// `ApiToken` row (see `auth::tokens`), and resolve its owner. Failure
244	/// semantics mirror the cookie path — every mismatch is a flat 401 that
245	/// never reveals which check failed.
246	async fn authenticate_bearer(
247	    state: &ConsoleState,
248	    presented: &str,
249	) -> Result<AuthSession, ConsoleApiError> {
250	    let hash = sha256_hex(presented.as_bytes());
251	    let token = store::get_api_token(&state.engine, &hash)
252	        .await?
253	        .ok_or_else(|| ConsoleApiError::Unauthorized("invalid api token".into()))?;
254	    if token.revoked_at.is_some() {
255	        return Err(ConsoleApiError::Unauthorized("api token revoked".into()));
256	    }
257	    let user = store::get_user(&state.engine, &token.user_id)
258	        .await?
259	        .ok_or_else(|| ConsoleApiError::Unauthorized("api token user gone".into()))?;
260	    if user.status != store::UserStatus::Active {
261	        return Err(ConsoleApiError::Unauthorized("user disabled".into()));
262	    }
263	    // `session_id` is opaque to callers; for a token-authenticated request
264	    // it is the token id (= hash). The cookie-only `logout` handler would
265	    // just no-op against `.xerj_sessions` for such an id.
266	    Ok(AuthSession {
267	        session_id: token.id,
268	        user,
269	    })
270	}
