272	/// Allow `Option<AuthSession>` extractors for endpoints that work
273	/// signed-in *or* signed-out (e.g. `/me` returns 401 explicitly rather
274	/// than relying on the rejection so the SPA can branch on it).
275	#[axum::async_trait]
276	impl FromRequestParts<ConsoleState> for OptionalAuthSession {
277	    type Rejection = std::convert::Infallible;
278	
279	    async fn from_request_parts(
280	        parts: &mut Parts,
281	        state: &ConsoleState,
282	    ) -> Result<Self, Self::Rejection> {
283	        match AuthSession::from_request_parts(parts, state).await {
284	            Ok(s) => Ok(OptionalAuthSession(Some(s))),
285	            Err(_) => Ok(OptionalAuthSession(None)),
286	        }
287	    }
288	}
