302	/// Helper for handlers that need to know if the request hit us over
303	/// HTTPS. We don't have direct TLS info inside axum (that's at the
304	/// listener layer), so we approximate by checking the `forwarded` /
305	/// `x-forwarded-proto` headers a reverse proxy sets, defaulting to
306	/// false (= http) so the local dev cookie still works.
307	pub fn request_is_secure(parts: &Parts) -> bool {
308	    if let Some(v) = parts.headers.get("x-forwarded-proto") {
309	        if v.as_bytes().eq_ignore_ascii_case(b"https") {
310	            return true;
311	        }
312	    }
313	    if let Some(v) = parts.headers.get("forwarded") {
314	        if let Ok(s) = v.to_str() {
315	            for part in s.split(';') {
316	                if part.trim().to_ascii_lowercase().starts_with("proto=https") {
317	                    return true;
318	                }
319	            }
320	        }
321	    }
322	    false
323	}
