370	        store::Session {
371	            id: id.to_string(),
372	            user_id: "u1".into(),
373	            created_at: now_iso(),
374	            expires_at: crate::time::epoch_ms_to_iso(now_epoch_ms() + 3_600_000),
375	            last_seen_at: crate::time::epoch_ms_to_iso(now_epoch_ms() - 600_000),
376	            ip: None,
