410	        let (engine, _dir) = test_engine().await;
411	        let mut s = session("s-live", false);
412	        s.last_seen_at = crate::time::epoch_ms_to_iso(now_epoch_ms() - 600_000);
413	        let before = s.last_seen_at.clone();
414	        store::put_session(&engine, &s).await.unwrap();
415	
416	        bump_last_seen(&engine, "s-live").await;
