146	async fn console_page_is_served_with_the_content_security_policy() {
147	    let (router, _dir) = boot();
148	    for path in ["/_xerj-console/", "/_xerj-console/index.html"] {
149	        let h = headers_of(router.clone(), path).await;
150	        let csp = h
151	            .get("content-security-policy")
152	            .unwrap_or_else(|| panic!("{path}: no Content-Security-Policy"))
153	            .to_str()
154	            .unwrap();
155	        assert_eq!(csp, xerj_console_api::spa::CONSOLE_CSP);
156	        assert_eq!(h.get("referrer-policy").unwrap(), "no-referrer");
157	        assert_eq!(h.get("x-content-type-options").unwrap(), "nosniff");
158	        assert_eq!(h.get("cache-control").unwrap(), "no-cache");
159	    }
160	
161	    // What the policy has to say, whatever else it grows: scripts and
162	    // connections from this origin only, and nothing that re-opens inline
163	    // script or eval.
164	    let csp = xerj_console_api::spa::CONSOLE_CSP;
165	    let directive = |name: &str| -> Vec<&str> {
166	        csp.split(';')
167	            .map(str::trim)
168	            .find(|d| d.split(' ').next() == Some(name))
169	            .unwrap_or_else(|| panic!("CSP has no {name} directive"))
170	            .split(' ')
171	            .skip(1)
172	            .collect()
173	    };
174	    assert_eq!(directive("script-src"), ["'self'"]);
175	    assert_eq!(directive("connect-src"), ["'self'"]);
176	    assert_eq!(directive("default-src"), ["'none'"]);
177	    assert_eq!(directive("object-src"), ["'none'"]);
178	    assert_eq!(directive("base-uri"), ["'none'"]);
179	    assert_eq!(directive("frame-ancestors"), ["'none'"]);
180	    assert!(!csp.contains("unsafe-eval"));
181	    assert!(!directive("script-src").contains(&"'unsafe-inline'"));
182	
183	    // login / setup carry an inline module script and show no document data:
184	    // they are served without the policy (it would stop them working).
185	    for path in ["/_xerj-console/login", "/_xerj-console/setup"] {
186	        let h = headers_of(router.clone(), path).await;
187	        assert!(h.get("content-security-policy").is_none(), "{path}");
188	        assert_eq!(h.get("x-content-type-options").unwrap(), "nosniff");
189	    }
190	}
