146	async fn highlights_pass_through_with_the_callers_tags_and_unescaped_text() {
147	    let app = boot().await;
148	    let (status, body) = call(
149	        &app,
150	        "POST",
151	        SEARCH,
152	        Some(json!({
153	            "query": { "match": { "email_subject": "invoice" } },
154	            "highlight": reader_highlight(),
155	        })),
156	    )
157	    .await;
158	    assert_eq!(status, 200, "{body}");
159	    let hit = &body["hits"]["hits"][0];
160	    assert_eq!(hit["_id"], "m1");
161	    assert_eq!(hit["_source"]["email_subject"], HOSTILE);
162	
163	    let frags = hit["highlight"]["email_subject"]
164	        .as_array()
165	        .unwrap_or_else(|| panic!("the proxy dropped the highlight block: {hit}"));
166	    let frag = frags[0].as_str().unwrap();
167	    assert!(
168	        frag.contains(&format!("{PRE}invoice{POST}")),
169	        "match must be wrapped in the caller's tags, got {frag:?}"
170	    );
171	    assert!(
172	        !frag.contains("<em>"),
173	        "the proxy fell back to the default <em> tags: {frag:?}"
174	    );
175	    // Raw document text: the markup characters arrive as themselves. The SPA
176	    // turns a fragment into text nodes; a pre-escaped fragment would display
177	    // as `&lt;img…`, and a fragment treated as HTML would be an XSS.
178	    assert!(
179	        frag.contains("<img src=x onerror=alert(1)>"),
180	        "fragment text must not be HTML-escaped by the engine or the proxy: {frag:?}"
181	    );
182	}
