1	//! Pluggable data sources.
2	//!
3	//! Phase-3 scope: the **read** half — list connections, list indices on
4	//! a connection, list fields on an index — backed by a single
5	//! auto-provisioned `built-in` connection that talks straight to the
6	//! in-process Engine.  This is enough for the SPA to drop its
7	//! hand-rolled `data-sources.js` overlay.
8	//!
9	//! **External-connection disclosure.** Only the `built-in` connection is
10	//! backed by a live adapter; its index and field listings are read
11	//! straight from the running Engine's real schema, never a canned map.
12	//! No external adapter subsystem exists yet — the adapter trait,
13	//! encrypted credentials, write paths (POST/PATCH/DELETE) and the
14	//! HTTP-shaped adapters (xerj-remote, elasticsearch, opensearch,
15	//! prometheus, postgres) all land in a follow-up commit.  Until then,
16	//! listing indices or fields for any non-`built-in` connection id
17	//! returns `501 Not Implemented` rather than a fabricated answer, and a
18	//! connection row that is not `built-in` is reported with status
19	//! `"unknown"` (no live probe is performed) so the UI never shows a
20	//! green light it cannot stand behind.
21	
22	use axum::{
23	    extract::{Path, State},
24	    response::{IntoResponse, Response},
25	    Json,
26	};
27	use serde::Serialize;
28	use serde_json::{json, Value};
29	
30	use crate::auth::sessions::AuthSession;
31	use crate::error::{ConsoleApiError, ConsoleResult};
32	use crate::indices;
33	use crate::response::ok;
34	use crate::state::ConsoleState;
35	use crate::time::now_iso;
36	
37	/// Indices the data-sources surface must pretend do not exist: the Console's
38	/// own `.xerj_*` system indices, and the reserved `.xerj-memory-*` namespace
39	/// holding per-tenant brains / agent memories. The latter is enforced on the
40	/// data plane by `xerj-api`'s authz middleware, but the Console router is
41	/// merged onto the engine routers *after* their layers, so that middleware
42	/// never runs here and the in-process engine calls below carry no visibility
43	/// scope (absent guard = engine-internal work, allow). This proxy is
44	/// therefore its own boundary and must refuse the namespace itself — with
45	/// the same NotFound as a system index, so existence doesn't leak.
46	pub(crate) fn is_hidden_index(name: &str) -> bool {
47	    indices::is_system_index(name) || xerj_common::types::is_reserved_index(name)
48	}
49	
50	/// Connection record — one row in `.xerj_connections`. Phase-3 only
51	/// surfaces the built-in adapter; adding new connections lands once the
52	/// AEAD-at-rest path for `auth.secret` is implemented.
53	#[derive(Debug, Clone, Serialize, serde::Deserialize)]
54	pub struct Connection {
55	    pub id: String,
56	    pub name: String,
57	    pub kind: String,
58	    #[serde(default)]
59	    pub url: Option<String>,
60	    #[serde(default = "default_true")]
61	    pub default: bool,
62	    #[serde(default = "default_true")]
63	    pub managed: bool,
64	    pub created_at: String,
65	    pub created_by: String,
66	    pub etag: String,
67	}
68	
69	fn default_true() -> bool {
70	    true
71	}
72	
73	const BUILTIN_ID: &str = "built-in";
74	
75	// ─────────────────────────────────────────────────────────────────────────────
76	// LIST
77	// ─────────────────────────────────────────────────────────────────────────────
78	
79	pub async fn list_connections(
80	    State(state): State<ConsoleState>,
81	    _sess: AuthSession,
82	) -> ConsoleResult<Response> {
83	    ensure_builtin(&state).await?;
84	    let idx = state.engine.get_index(indices::CONNECTIONS)?;
85	    let body = json!({
86	        "query": { "match_all": {} },
87	        "size": 100
88	    });
89	    let req = xerj_query::parser::parse_request(&body)
90	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
91	    let r = idx.search(&req).await?;
92	
93	    let mut conns: Vec<Connection> = Vec::with_capacity(r.hits.len());
94	    for h in r.hits {
95	        if let Ok(c) = serde_json::from_value::<Connection>(h.source) {
96	            conns.push(c);
97	        }
98	    }
99	
100	    // Decorate with live status — for now, only `built-in` is live, and
101	    // it's always green if the engine itself is responding (we're inside
102	    // it).  External adapters add real probing in a later commit.
103	    let mut out: Vec<Value> = Vec::with_capacity(conns.len());
104	    for c in conns {
105	        let status = if c.id == BUILTIN_ID {
106	            "green"
107	        } else {
108	            "unknown"
109	        };
110	        let mut v = serde_json::to_value(&c)?;
111	        v["status"] = Value::String(status.into());
112	        v["last_checked_at"] = Value::String(now_iso());
113	        out.push(v);
114	    }
115	
116	    Ok(ok(json!({ "connections": out, "total": out.len() }), None))
117	}
118	
119	// ─────────────────────────────────────────────────────────────────────────────
120	// INDICES
121	// ─────────────────────────────────────────────────────────────────────────────
122	
123	pub async fn list_indices(
124	    State(state): State<ConsoleState>,
125	    _sess: AuthSession,
126	    Path(conn_id): Path<String>,
127	) -> ConsoleResult<Response> {
128	    ensure_builtin(&state).await?;
129	
130	    if conn_id != BUILTIN_ID {
131	        // External adapters land in a later commit; everything that
132	        // isn't built-in is a stub for now.
133	        return Err(ConsoleApiError::NotImplemented(format!(
134	            "connection '{conn_id}' adapter not yet implemented"
135	        )));
136	    }
137	
138	    // Walk the engine's indices via its public listing surface.  Skip
139	    // `.xerj_*` system indices and reserved `.xerj-memory-*` brains (see
140	    // `is_hidden_index`) — neither is a user data source.
141	    let mut items: Vec<Value> = Vec::new();
142	    for name in state.engine.index_name_list() {
143	        if is_hidden_index(&name) {
144	            continue;
145	        }
146	        let idx = match state.engine.get_index(&name) {
147	            Ok(i) => i,
148	            Err(_) => continue,
149	        };
150	        let stats = idx.stats().await;
151	        items.push(json!({
152	            "name": name,
153	            "docs": stats.doc_count,
154	            "segments": stats.segment_count,
155	            "fields": stats.field_count,
156	            // On-disk store bytes, measured from the index's data dir —
157	            // the same number /_cat/indices reports (es_compat's
158	            // dir_size_bytes, mirrored in knowledge.rs for this crate).
159	            "bytes": crate::knowledge::dir_size_bytes(idx.data_dir()),
160	            "shards": 1,
161	            "replicas": 0,
162	        }));
163	    }
164	    items.sort_by(|a, b| {
165	        a["name"]
166	            .as_str()
167	            .unwrap_or("")
168	            .cmp(b["name"].as_str().unwrap_or(""))
169	    });
170	    Ok(ok(json!({ "indices": items, "total": items.len() }), None))
171	}
172	
173	// ─────────────────────────────────────────────────────────────────────────────
174	// FIELDS
175	// ─────────────────────────────────────────────────────────────────────────────
176	
177	pub async fn list_fields(
178	    State(state): State<ConsoleState>,
179	    _sess: AuthSession,
180	    Path((conn_id, index)): Path<(String, String)>,
181	) -> ConsoleResult<Response> {
182	    if conn_id != BUILTIN_ID {
183	        return Err(ConsoleApiError::NotImplemented(format!(
184	            "connection '{conn_id}' adapter not yet implemented"
185	        )));
186	    }
187	    if is_hidden_index(&index) {
188	        return Err(ConsoleApiError::NotFound(format!("index {index}")));
189	    }
190	    let idx = state
191	        .engine
192	        .get_index(&index)
193	        .map_err(|_| ConsoleApiError::NotFound(format!("index {index}")))?;
194	    let schema = idx.schema().await;
195	    let fields: Vec<Value> = schema
196	        .fields
197	        .iter()
198	        .map(|f| {
199	            json!({
200	                "name": f.name,
201	                "type": f.field_type.to_string(),
202	                "indexed": f.options.indexed,
203	                "doc_values": f.options.doc_values,
204	                // A `semantic_text` field is a text field with an embedding
205	                // config; `type` alone reads "text". The console derives
206	                // which field `semantic` / `hybrid` run against from this
207	                // flag: it holds a session, not an engine API key, so on an
208	                // auth-enabled engine it cannot read `GET /{index}/_mapping`.
209	                "semantic": f.embedding.is_some(),
210	            })
211	        })
212	        .collect();
213	    Ok(ok(json!({ "fields": fields, "total": fields.len() }), None))
214	}
215	
216	// ─────────────────────────────────────────────────────────────────────────────
217	// SEARCH
218	// ─────────────────────────────────────────────────────────────────────────────
219	
220	/// Run an ES-compat `_search` against a single index, authenticated by the
221	/// caller's Console session instead of a data-plane API key.
222	///
223	/// **Why this exists.** The SPA's declarative dashboard panels
224	/// (`xerj-ux/src/data/panel-query.js`) and the built-in dashboard adapters
225	/// (`xerj-ux/src/data/backends/xerj.js`) used to `fetch()` `/{index}/_search`
226	/// directly, same-origin, with no `Authorization` header at all. That is
227	/// silently correct only when the engine is started with `--insecure`; on
228	/// any auth-enabled deployment — the default, recommended posture — every
229	/// such call gets a 401 the caller doesn't even look at (`backends/xerj.js`
230	/// treats any failure as "no live adapter, fall back to mock"), so the
231	/// entire "real dashboards" feature quietly regresses to demo data with no
232	/// visible error. This endpoint reuses the session-cookie gate every other
233	/// `data-sources` route already has (see `list_indices` / `list_fields`
234	/// above) and talks to the engine in-process — no data-plane credential is
235	/// needed at all, the same way `list_indices`/`list_fields` already read
236	/// the schema/stats in-process.
237	///
238	/// **Scope.** Single, exact index names only, matching `list_fields`'s
239	/// existing scope — no wildcard/`_all` resolution or multi-index merge
240	/// here (that logic is non-trivial and already lives, correctly, in
241	/// `xerj-api::es_compat`; duplicating a second copy risks exactly the kind
242	/// of subtle merge bug that logic has already been hardened against).
243	/// Callers that need a pattern get a clear `501`, not a silent wrong
244	/// answer — consistent with how this file already treats non-`built-in`
245	/// connections.
246	pub async fn search(
247	    State(state): State<ConsoleState>,
248	    _sess: AuthSession,
249	    Path((conn_id, index)): Path<(String, String)>,
250	    Json(body): Json<Value>,
251	) -> ConsoleResult<Response> {
252	    if conn_id != BUILTIN_ID {
253	        return Err(ConsoleApiError::NotImplemented(format!(
254	            "connection '{conn_id}' adapter not yet implemented"
255	        )));
256	    }
257	    if index.contains('*') || index == "_all" || index.split(',').count() > 1 {
258	        return Err(ConsoleApiError::NotImplemented(
259	            "panel search proxy supports a single exact index name only; \
260	             wildcard/_all/multi-index queries are not yet implemented"
261	                .into(),
262	        ));
263	    }
264	    if is_hidden_index(&index) {
265	        return Err(ConsoleApiError::NotFound(format!("index {index}")));
266	    }
267	    let idx = state
268	        .engine
269	        .get_index(&index)
270	        .map_err(|_| ConsoleApiError::NotFound(format!("index {index}")))?;
271	
272	    let req = xerj_query::parser::parse_request(&body)
273	        .map_err(|e| ConsoleApiError::BadRequest(e.to_string()))?;
274	    let result = idx
275	        .search(&req)
276	        .await
277	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
278	
279	    let hits: Vec<Value> = result
280	        .hits
281	        .iter()
282	        .map(|h| {
283	            let mut hit = json!({
284	                "_index": index,
285	                "_id": h.id,
286	                "_score": h.score,
287	                "_source": h.source,
288	            });
289	            // Pass the engine's highlight fragments through when the request
290	            // asked for them, so the Reader can mark matches for a signed-in
291	            // operator the same way it does for a guest on the ES-compat
292	            // route. Fragments are raw document text with the caller's
293	            // pre/post tags spliced in — the SPA never parses them as markup
294	            // (`xerj-ux/src/ux/safe-dom.js#highlightChildren`).
295	            if let Some(hl) = &h.highlight {
296	                hit["highlight"] = json!(hl);
297	            }
298	            hit
299	        })
300	        .collect();
301	    let wire = json!({
302	        "took": result.took_ms,
303	        "timed_out": result.timed_out,
304	        "hits": {
305	            "total": { "value": result.total.value, "relation": result.total.relation },
306	            "max_score": result.max_score,
307	            "hits": hits,
308	        },
309	        "aggregations": result.aggs,
310	    });
311	    Ok(Json(wire).into_response())
312	}
313	
314	// ─────────────────────────────────────────────────────────────────────────────
315	// Built-in auto-provisioning
316	// ─────────────────────────────────────────────────────────────────────────────
317	
318	async fn ensure_builtin(state: &ConsoleState) -> ConsoleResult<()> {
319	    let idx = state.engine.get_index(indices::CONNECTIONS)?;
320	    let body = json!({
321	        "query": { "ids": { "values": [BUILTIN_ID] } },
322	        "size": 1
323	    });
324	    let req = xerj_query::parser::parse_request(&body)
325	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
326	    let r = idx.search(&req).await?;
327	    if !r.hits.is_empty() {
328	        return Ok(());
329	    }
330	    let conn = Connection {
331	        id: BUILTIN_ID.into(),
332	        name: "Local Xerj".into(),
333	        kind: "xerj-local".into(),
334	        url: None,
335	        default: true,
336	        managed: true,
337	        created_at: now_iso(),
338	        created_by: "system".into(),
339	        etag: "1".into(),
340	    };
341	    idx.index_document(Some(BUILTIN_ID.into()), serde_json::to_value(&conn)?)
342	        .await?;
343	    Ok(())
344	}
