1	//! System indices used by Xerj Console.
2	//!
3	//! All Xerj Console persistent state lives in hidden indices prefixed with `.xerj_`.
4	//! These are created on first boot if missing. Schema is intentionally
5	//! minimal — only the fields we actually filter or sort on get a typed
6	//! mapping; everything else is stored in `_source` and read back as-is.
7	//!
8	//! Hidden semantics: `_cat/indices` skips these by default. Admin tools
9	//! that want to see them pass `?include_system=true` (an enhancement to
10	//! the existing `_cat/indices` handler — wired up in a follow-up commit).
11	
12	use xerj_common::types::{FieldConfig, FieldType, Schema};
13	use xerj_engine::Engine;
14	
15	use crate::error::{ConsoleApiError, ConsoleResult};
16	
17	// ─────────────────────────────────────────────────────────────────────────────
18	// Index names
19	// ─────────────────────────────────────────────────────────────────────────────
20	
21	pub const USERS: &str = ".xerj_users";
22	pub const PASSKEYS: &str = ".xerj_passkeys";
23	pub const MAGIC_LINKS: &str = ".xerj_magic_links";
24	pub const SESSIONS: &str = ".xerj_sessions";
25	pub const API_TOKENS: &str = ".xerj_api_tokens";
26	pub const IDP_CONFIG: &str = ".xerj_idp_config";
27	pub const CLUSTER_STATE: &str = ".xerj_cluster_state";
28	pub const CONNECTIONS: &str = ".xerj_connections";
29	pub const PREFS: &str = ".xerj_prefs";
30	pub const DASHBOARDS: &str = ".xerj_dashboards";
31	pub const VIEWS: &str = ".xerj_views";
32	pub const ALERT_RULES: &str = ".xerj_alert_rules";
33	pub const ALERT_FIRES: &str = ".xerj_alert_fires";
34	pub const AUDIT: &str = ".xerj_audit";
35	
36	/// Every system index this crate owns. Iterated by `ensure_all`.
37	pub const ALL: &[&str] = &[
38	    USERS,
39	    PASSKEYS,
40	    MAGIC_LINKS,
41	    SESSIONS,
42	    API_TOKENS,
43	    IDP_CONFIG,
44	    CLUSTER_STATE,
45	    CONNECTIONS,
46	    PREFS,
47	    DASHBOARDS,
48	    VIEWS,
49	    ALERT_RULES,
50	    ALERT_FIRES,
51	    AUDIT,
52	];
53	
54	/// Predicate: is this index name owned by Xerj Console? Used by `_cat/indices`
55	/// to filter out system indices from the default listing.
56	pub fn is_system_index(name: &str) -> bool {
57	    name.starts_with(".xerj_")
58	}
59	
60	// ─────────────────────────────────────────────────────────────────────────────
61	// Schemas
62	// ─────────────────────────────────────────────────────────────────────────────
63	
64	/// Build the schema for a Xerj Console system index. Only fields we need to
65	/// filter / sort / aggregate on are typed; the rest of the document is
66	/// untyped JSON (stored in `_source`, read back as-is). This keeps the
67	/// mappings small and makes schema evolution a non-event for fields we
68	/// don't query on.
69	fn schema_for(index: &str) -> Schema {
70	    let mut s = Schema::empty();
71	    let add = |s: &mut Schema, name: &str, ty: FieldType| {
72	        let _ = s.add_field(FieldConfig::new(name, ty));
73	    };
74	
75	    match index {
76	        USERS => {
77	            // Filter: status=active, role=admin, email=…; sort: created_at
78	            add(&mut s, "email", FieldType::Keyword);
79	            add(&mut s, "role", FieldType::Keyword);
80	            add(&mut s, "status", FieldType::Keyword);
81	            add(&mut s, "created_at", FieldType::Date);
82	            add(&mut s, "last_seen_at", FieldType::Date);
83	            add(&mut s, "display_name", FieldType::Keyword);
84	        }
85	        PASSKEYS => {
86	            // Lookup: by user_id (login), by credential_id (assertion verify)
87	            add(&mut s, "user_id", FieldType::Keyword);
88	            add(&mut s, "credential_id", FieldType::Keyword);
89	            add(&mut s, "name", FieldType::Keyword);
90	            add(&mut s, "created_at", FieldType::Date);
91	            add(&mut s, "last_used_at", FieldType::Date);
92	        }
93	        MAGIC_LINKS => {
94	            // Lookup: by token_hash (= _id, but typed for completeness)
95	            add(&mut s, "purpose", FieldType::Keyword);
96	            add(&mut s, "user_id", FieldType::Keyword);
97	            add(&mut s, "email", FieldType::Keyword);
98	            add(&mut s, "role", FieldType::Keyword);
99	            add(&mut s, "created_by", FieldType::Keyword);
100	            add(&mut s, "created_at", FieldType::Date);
101	            add(&mut s, "expires_at", FieldType::Date);
102	            add(&mut s, "used_at", FieldType::Date);
103	        }
104	        SESSIONS => {
105	            // Lookup: by session_id (= _id), reverse by user_id
106	            add(&mut s, "user_id", FieldType::Keyword);
107	            add(&mut s, "created_at", FieldType::Date);
108	            add(&mut s, "expires_at", FieldType::Date);
109	            add(&mut s, "last_seen_at", FieldType::Date);
110	            add(&mut s, "ip", FieldType::Keyword);
111	            add(&mut s, "ua", FieldType::Keyword);
112	            add(&mut s, "idp", FieldType::Keyword);
113	            add(&mut s, "revoked_at", FieldType::Date);
114	        }
115	        API_TOKENS => {
116	            // Lookup: by token_hash (= _id), reverse by user_id; expire by exp
117	            add(&mut s, "user_id", FieldType::Keyword);
118	            add(&mut s, "name", FieldType::Keyword);
119	            add(&mut s, "scopes", FieldType::Keyword);
120	            add(&mut s, "created_at", FieldType::Date);
121	            add(&mut s, "last_used_at", FieldType::Date);
122	            add(&mut s, "revoked_at", FieldType::Date);
123	        }
124	        IDP_CONFIG => {
125	            // One row per protocol; no filter fields needed beyond _id.
126	            add(&mut s, "updated_at", FieldType::Date);
127	            add(&mut s, "updated_by", FieldType::Keyword);
128	        }
129	        CLUSTER_STATE => {
130	            // One row per node. Filter on role/term/leader.
131	            add(&mut s, "role", FieldType::Keyword);
132	            add(&mut s, "term", FieldType::Long);
133	            add(&mut s, "commit_index", FieldType::Long);
134	            add(&mut s, "last_applied", FieldType::Long);
135	            add(&mut s, "updated_at", FieldType::Date);
136	        }
137	        CONNECTIONS => {
138	            add(&mut s, "name", FieldType::Keyword);
139	            add(&mut s, "kind", FieldType::Keyword);
140	            add(&mut s, "default", FieldType::Boolean);
141	            add(&mut s, "managed", FieldType::Boolean);
142	            add(&mut s, "created_at", FieldType::Date);
143	            add(&mut s, "created_by", FieldType::Keyword);
144	            add(&mut s, "etag", FieldType::Keyword);
145	        }
146	        PREFS => {
147	            // _id = user_id; payload is opaque key/value pairs.
148	            add(&mut s, "updated_at", FieldType::Date);
149	        }
150	        DASHBOARDS => {
151	            add(&mut s, "owner", FieldType::Keyword);
152	            add(&mut s, "org_id", FieldType::Keyword);
153	            add(&mut s, "visibility", FieldType::Keyword);
154	            // Provenance marker for seeded built-ins; typed so admin tooling
155	            // can filter managed vs user dashboards. Panel contents stay
156	            // untyped in `_source` (see the panel-schema doc in dashboards.rs).
157	            add(&mut s, "managed", FieldType::Boolean);
158	            add(&mut s, "name", FieldType::Keyword);
159	            add(&mut s, "section", FieldType::Keyword);
160	            add(&mut s, "group", FieldType::Keyword);
161	            add(&mut s, "version", FieldType::Long);
162	            add(&mut s, "etag", FieldType::Keyword);
163	            add(&mut s, "created_at", FieldType::Date);
164	            add(&mut s, "updated_at", FieldType::Date);
165	            add(&mut s, "deleted_at", FieldType::Date);
166	        }
167	        VIEWS => {
168	            add(&mut s, "owner", FieldType::Keyword);
169	            add(&mut s, "org_id", FieldType::Keyword);
170	            add(&mut s, "dashboard_id", FieldType::Keyword);
171	            add(&mut s, "name", FieldType::Keyword);
172	            add(&mut s, "updated_at", FieldType::Date);
173	        }
174	        ALERT_RULES => {
175	            // The rule body itself (`watch`, `type`, `etag`) is written by
176	            // the engine-side watcher (xerj-api `PUT /_watcher/watch/{id}`,
177	            // #1062) — this crate owns the INDEX and its typed filter
178	            // fields; xerj-api deliberately does not depend on this crate,
179	            // so both sides write/read through the shared Engine.
180	            add(&mut s, "owner", FieldType::Keyword);
181	            add(&mut s, "org_id", FieldType::Keyword);
182	            add(&mut s, "name", FieldType::Keyword);
183	            add(&mut s, "enabled", FieldType::Boolean);
184	            add(&mut s, "etag", FieldType::Keyword);
185	            add(&mut s, "updated_at", FieldType::Date);
186	        }
187	        ALERT_FIRES => {
188	            // Written by the watcher evaluator (#1062). `p` is the RAW
189	            // /_decide confidence (calibration is #1063), typed so the
190	            // console can filter/sort by it; `calibrated` lives in `_source`
191	            // (constant false today, so filtering on it is pointless).
192	            add(&mut s, "rule_id", FieldType::Keyword);
193	            add(&mut s, "level", FieldType::Keyword);
194	            add(&mut s, "fired_at", FieldType::Date);
195	            // The document whose decide vote fired this rule.
196	            add(&mut s, "doc_id", FieldType::Keyword);
197	            // Raw (uncalibrated, #1063) /_decide confidence of the vote.
198	            add(&mut s, "p", FieldType::Double);
199	            // Which decide tier answered: "history" | "local".
200	            add(&mut s, "tier", FieldType::Keyword);
201	        }
202	        AUDIT => {
203	            add(&mut s, "who", FieldType::Keyword);
204	            add(&mut s, "when", FieldType::Date);
205	            add(&mut s, "action", FieldType::Keyword);
206	            add(&mut s, "resource", FieldType::Keyword);
207	            add(&mut s, "resource_id", FieldType::Keyword);
208	            add(&mut s, "ip", FieldType::Keyword);
209	        }
210	        _ => {} // Unknown name: empty schema, dynamic mapping picks it up.
211	    }
212	    s
213	}
