216	// Auto-create
217	// ─────────────────────────────────────────────────────────────────────────────
218	
219	/// Idempotently create every Xerj Console system index, applying the schema
220	/// from `schema_for`. Does nothing for indices that already exist.
221	///
222	/// Logs a single `info` line on first creation and returns the names
223	/// that were newly created (so the bootstrap module can detect "fresh
224	/// data dir" purely from the create-set being non-empty).
225	pub fn ensure_all(engine: &Engine) -> ConsoleResult<Vec<&'static str>> {
226	    let mut created = Vec::new();
227	    for name in ALL {
228	        if engine.get_index(name).is_ok() {
229	            continue;
230	        }
231	        let schema = schema_for(name);
232	        engine
233	            .create_index(name, schema)
234	            .map_err(|e| ConsoleApiError::Internal(format!("create {name}: {e}")))?;
235	        tracing::info!(index = *name, "created xerj-console system index");
236	        created.push(*name);
237	    }
238	    Ok(created)
239	}
