1	//! The Console data-sources proxy must not cross the per-tenant brain
2	//! boundary (RC10 blocker B1).
3	//!
4	//! The data plane guards the reserved `.xerj-memory-*` namespace in
5	//! `xerj_api::authz` middleware, but the Console router is merged onto the
6	//! engine routers *after* their layers are applied (`xerj-server::main`), so
7	//! that middleware never runs on `/_xerj-console/*` and no index-visibility
8	//! scope is installed. The data-sources handlers talk to the engine
9	//! in-process, where an absent guard means "engine-internal work, allow" —
10	//! so any authenticated Console session of any role could read any tenant's
11	//! brain through the search/fields/indices proxy. These tests pin the fix:
12	//! the proxy refuses the reserved namespace itself, with the same NotFound
13	//! it already gives `.xerj_*` system indices, so existence doesn't leak.
14	
15	use axum::{body::Body, http::Request, Router};
16	use http_body_util::BodyExt;
17	use serde_json::{json, Value};
18	use tempfile::TempDir;
19	use tower::ServiceExt;
20	use xerj_common::config::Config;
21	use xerj_common::types::Schema;
22	use xerj_console_api::{
23	    auth::{sessions, store},
24	    state::ClusterMode,
25	    xerj_console_router, ConsoleState,
26	};
27	use xerj_engine::Engine;
28	
29	/// A secret that must never appear in any Console response body.
30	const ALICE_SECRET: &str = "alice-private-fact-9f83c1";
31	
32	struct TestApp {
33	    router: Router,
34	    cookie: String,
35	    _dir: TempDir,
36	}
37	
38	/// Boot the console with an authenticated owner session — the strongest
39	/// role there is. If even the owner cannot reach a brain through the
40	/// proxy, no session can.
41	async fn boot_with_brain() -> TestApp {
42	    let dir = TempDir::new().unwrap();
43	    let mut cfg = Config::default();
44	    cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
45	    let engine = Engine::new(cfg).expect("engine");
46	    let outcome = xerj_console_api::bootstrap::run(&engine, dir.path(), "http://localhost:9200")
47	        .await
48	        .unwrap();
49	    let state = ConsoleState::new(
50	        engine.clone(),
51	        "local".into(),
52	        outcome.master_key,
53	        ClusterMode::Standalone,
54	    );
55	
56	    let user = store::User {
57	        id: "owner-test".to_string(),
58	        email: "owner@example.com".to_string(),
59	        display_name: "Owner".to_string(),
60	        role: "owner".to_string(),
61	        status: store::UserStatus::Active,
62	        created_at: xerj_console_api::time::now_iso(),
63	        last_seen_at: Some(xerj_console_api::time::now_iso()),
64	    };
65	    store::upsert_user(&engine, &user).await.unwrap();
66	    let (_session, signed) = sessions::mint_session(&state, &user.id, "passkey", None, None)
67	        .await
68	        .unwrap();
69	    let cookie = format!("xerj_session={signed}");
70	
71	    // Another tenant's brain, exactly as memory_api provisions it: the
72	    // namespace index plus its -edges sibling, both in the reserved prefix.
73	    engine
74	        .create_index(".xerj-memory-alice", Schema::empty())
75	        .expect("create brain index");
76	    engine
77	        .create_index(".xerj-memory-alice-edges", Schema::empty())
78	        .expect("create brain edges index");
79	    let brain = engine.get_index(".xerj-memory-alice").unwrap();
80	    brain
81	        .create_document("m1".into(), json!({ "content": ALICE_SECRET }))
82	        .await
83	        .expect("write brain doc");
84	
85	    let router = xerj_console_router(state);
86	    TestApp {
87	        router,
88	        cookie,
89	        _dir: dir,
90	    }
91	}
