93	async fn body_json(resp: axum::response::Response) -> (axum::http::StatusCode, Value) {
94	    let status = resp.status();
95	    let bytes = resp.into_body().collect().await.unwrap().to_bytes();
96	    let v = if bytes.is_empty() {
97	        Value::Null
98	    } else {
99	        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
100	    };
101	    (status, v)
102	}
103	
104	fn req(method: &str, path: &str, cookie: &str, body: Option<Value>) -> Request<Body> {
105	    let body = match body {
106	        Some(b) => Body::from(b.to_string()),
107	        None => Body::empty(),
108	    };
109	    Request::builder()
110	        .method(method)
111	        .uri(path)
112	        .header("cookie", cookie)
113	        .header("content-type", "application/json")
114	        .body(body)
115	        .unwrap()
116	}
