118	#[tokio::test]
119	async fn search_cannot_read_a_brain() {
120	    let app = boot_with_brain().await;
121	
122	    let r = app
123	        .router
124	        .clone()
125	        .oneshot(req(
126	            "POST",
127	            "/_xerj-console/api/v1/data-sources/connections/built-in/indices/.xerj-memory-alice/search",
128	            &app.cookie,
129	            Some(json!({ "query": { "match_all": {} } })),
130	        ))
131	        .await
132	        .unwrap();
133	    let (status, body) = body_json(r).await;
134	    assert_eq!(status, 404, "brain search must 404, got: {body}");
135	    assert!(
136	        !body.to_string().contains(ALICE_SECRET),
137	        "brain content leaked: {body}"
138	    );
139	
140	    // No existence oracle: a brain that exists and one that doesn't must be
141	    // indistinguishable through this endpoint.
142	    let r = app
143	        .router
144	        .oneshot(req(
145	            "POST",
146	            "/_xerj-console/api/v1/data-sources/connections/built-in/indices/.xerj-memory-nobody/search",
147	            &app.cookie,
148	            Some(json!({ "query": { "match_all": {} } })),
149	        ))
150	        .await
151	        .unwrap();
152	    let (ghost_status, ghost_body) = body_json(r).await;
153	    assert_eq!(status, ghost_status);
154	    assert_eq!(
155	        body.to_string().replace("alice", "nobody"),
156	        ghost_body.to_string(),
157	        "existing vs missing brain must be indistinguishable"
158	    );
159	}
