1	//! First-launch bootstrap.
2	//!
3	//! Two responsibilities:
4	//!
5	//! 1. **Master key.** Load (or generate-then-persist) a 32-byte secret used
6	//!    to HMAC session cookies, magic-link tokens, and connection-secret
7	//!    AEAD keys. Stored at `<data_dir>/.xerj_master_key` mode 0600, or
8	//!    overridden by the `XERJ_CONSOLE_KEY` env var (32 hex bytes).
9	//!
10	//! 2. **Bootstrap mode.** If `.xerj_users` has zero documents with
11	//!    `status = "active"`, mint a single-use 30-minute magic link with
12	//!    `purpose = "bootstrap"` and `role = "owner"`, store its sha256 in
13	//!    `.xerj_magic_links`, and print a bordered banner to stderr with
14	//!    the redeem URL the operator should open.
15	//!
16	//! Idempotent: if an active user already exists, this function is a no-op
17	//! beyond loading the master key.
18	
19	use std::path::Path;
20	
21	use rand::RngCore;
22	use serde_json::{json, Value};
23	use sha2::{Digest, Sha256};
24	use xerj_engine::Engine;
25	
26	use crate::error::{ConsoleApiError, ConsoleResult};
27	use crate::indices;
28	use crate::time::{now_epoch_ms, now_iso};
29	
30	/// Result of the bootstrap routine, returned to the server's main()
31	/// so it can fold the master key into `ConsoleState` and decide what to
32	/// print on stdout.
33	pub struct BootstrapOutcome {
34	    pub master_key: [u8; 32],
35	    /// `Some(url)` if a fresh bootstrap link was minted. The caller is
36	    /// responsible for printing this — `bootstrap_if_needed` does its
37	    /// own stderr banner already, but tests want the URL programmatically.
38	    pub magic_link: Option<String>,
39	}
40	
41	/// Run the full first-launch routine. Idempotent on subsequent boots.
42	///
43	/// `bind_url` is the URL the operator should browse to (e.g.
44	/// `http://localhost:9200`). The full link the SPA receives is
45	/// `{bind_url}/_xerj-console/setup#token=…`.
46	pub async fn run(
47	    engine: &Engine,
48	    data_dir: &Path,
49	    bind_url: &str,
50	) -> ConsoleResult<BootstrapOutcome> {
51	    // Console bootstrap is a storage migration: it creates fourteen system
52	    // indices, writes a master key and publishes seeded dashboard segments.
53	    // Keep this guard inside the crate as well as at the server call site so a
54	    // future embedder cannot accidentally bypass the compatibility fence.
55	    if !engine.cluster_state_boot_status().is_writable() {
56	        return Err(ConsoleApiError::Internal(
57	            "cluster-state storage is unavailable; Console bootstrap requires a supported restart"
58	                .to_owned(),
59	        ));
60	    }
61	    let master_key = load_or_init_master_key(data_dir)?;
62	
63	    indices::ensure_all(engine)?;
64	
65	    // Materialise the built-in dashboards as editable backend data. Idempotent
66	    // and safe on every boot: creates any missing default, never clobbers an
67	    // operator's edits, and only re-syncs untouched defaults when the shipped
68	    // seed revision is bumped. See `crate::seed`.
69	    crate::seed::seed_default_dashboards(engine).await?;
70	
71	    let magic_link = if has_any_active_user(engine).await? {
72	        None
73	    } else {
74	        let url = mint_bootstrap_link(engine, bind_url).await?;
75	        print_bootstrap_banner(&url);
76	        Some(url)
77	    };
78	
79	    Ok(BootstrapOutcome {
80	        master_key,
81	        magic_link,
82	    })
83	}
84	
85	// ─────────────────────────────────────────────────────────────────────────────
86	// Master key
87	// ─────────────────────────────────────────────────────────────────────────────
88	
89	const MASTER_KEY_FILENAME: &str = ".xerj_master_key";
90	const MASTER_KEY_ENV: &str = "XERJ_CONSOLE_KEY";
91	
92	fn load_or_init_master_key(data_dir: &Path) -> ConsoleResult<[u8; 32]> {
93	    // Env var wins — covers Kubernetes secret mounts.
94	    if let Ok(hex) = std::env::var(MASTER_KEY_ENV) {
95	        let bytes = hex_decode(hex.trim()).ok_or_else(|| {
96	            ConsoleApiError::Internal(format!("{MASTER_KEY_ENV}: not 64 hex chars"))
97	        })?;
98	        if bytes.len() != 32 {
99	            return Err(ConsoleApiError::Internal(format!(
100	                "{MASTER_KEY_ENV}: expected 32 bytes (64 hex), got {}",
101	                bytes.len()
102	            )));
103	        }
104	        let mut out = [0u8; 32];
105	        out.copy_from_slice(&bytes);
106	        return Ok(out);
107	    }
108	
109	    let path = data_dir.join(MASTER_KEY_FILENAME);
110	    if path.exists() {
111	        let raw = std::fs::read_to_string(&path)?;
112	        let trimmed = raw.trim();
113	        let bytes = hex_decode(trimmed).ok_or_else(|| {
114	            ConsoleApiError::Internal(format!(
115	                "{}: not valid hex (corrupt? regenerate by deleting and restarting)",
116	                path.display()
117	            ))
118	        })?;
119	        if bytes.len() != 32 {
120	            return Err(ConsoleApiError::Internal(format!(
121	                "{}: expected 32 bytes (64 hex), got {}",
122	                path.display(),
123	                bytes.len()
124	            )));
125	        }
126	        let mut out = [0u8; 32];
127	        out.copy_from_slice(&bytes);
128	        return Ok(out);
129	    }
130	
131	    // First boot: generate, persist with mode 0600.
132	    let mut key = [0u8; 32];
133	    rand::thread_rng().fill_bytes(&mut key);
134	    let hex = hex_encode(&key);
135	    std::fs::write(&path, &hex)?;
136	    set_owner_readable_only(&path)?;
137	    tracing::info!(path = %path.display(), "generated xerj-console master key");
138	    Ok(key)
139	}
140	
141	#[cfg(unix)]
142	fn set_owner_readable_only(p: &Path) -> std::io::Result<()> {
143	    use std::os::unix::fs::PermissionsExt;
144	    let mut perm = std::fs::metadata(p)?.permissions();
145	    perm.set_mode(0o600);
146	    std::fs::set_permissions(p, perm)
147	}
148	
149	#[cfg(not(unix))]
150	fn set_owner_readable_only(_p: &Path) -> std::io::Result<()> {
151	    Ok(())
152	}
153	
154	// ─────────────────────────────────────────────────────────────────────────────
155	// "Any active user?" predicate
156	// ─────────────────────────────────────────────────────────────────────────────
157	
158	async fn has_any_active_user(engine: &Engine) -> ConsoleResult<bool> {
159	    let idx = engine
160	        .get_index(indices::USERS)
161	        .map_err(|e| ConsoleApiError::Internal(format!("open {}: {e}", indices::USERS)))?;
162	
163	    // Build a `term: { status: "active" }` search with size: 1. Cheap on
164	    // a tiny system index — we only care whether any doc matches.
165	    let body = json!({
166	        "query": { "term": { "status": "active" } },
167	        "size": 1,
168	        "track_total_hits": true
169	    });
170	
171	    let req = xerj_query::parser::parse_request(&body)
172	        .map_err(|e| ConsoleApiError::Internal(format!("parse bootstrap probe: {e}")))?;
173	
174	    let result = idx
175	        .search(&req)
176	        .await
177	        .map_err(|e| ConsoleApiError::Internal(format!("search {}: {e}", indices::USERS)))?;
178	
179	    Ok(result.total.value > 0)
180	}
181	
182	// ─────────────────────────────────────────────────────────────────────────────
183	// Magic link minting
184	// ─────────────────────────────────────────────────────────────────────────────
185	
186	/// Format of the token the operator pastes into a browser. Random 32 bytes,
187	/// URL-safe base64 (no padding) — always 43 chars. We never log or store
188	/// the token in plaintext; only its sha256 lands in `.xerj_magic_links`.
189	const TOKEN_BYTES: usize = 32;
190	const BOOTSTRAP_TTL_MS: i64 = 30 * 60 * 1000; // 30 minutes
191	
192	async fn mint_bootstrap_link(engine: &Engine, bind_url: &str) -> ConsoleResult<String> {
193	    let idx = engine
194	        .get_index(indices::MAGIC_LINKS)
195	        .map_err(|e| ConsoleApiError::Internal(format!("open {}: {e}", indices::MAGIC_LINKS)))?;
196	
197	    let token = random_url_token();
198	    let token_hash = sha256_hex(token.as_bytes());
199	
200	    let now_ms = now_epoch_ms();
201	    let expires_ms = now_ms + BOOTSTRAP_TTL_MS;
202	
203	    let doc: Value = json!({
204	        "purpose":     "bootstrap",
205	        "role":        "owner",
206	        "user_id":     null,
207	        "email":       null,
208	        "created_by":  "system",
209	        "created_at":  now_iso(),
210	        "expires_at":  crate::time::epoch_ms_to_iso(expires_ms),
211	        "used_at":     null,
212	        "used_from_ip": null
213	    });
214	
215	    idx.create_document(token_hash.clone(), doc)
216	        .await
217	        .map_err(|e| ConsoleApiError::Internal(format!("write magic link: {e}")))?;
218	
219	    Ok(format!(
220	        "{}/_xerj-console/setup#token={}",
221	        bind_url.trim_end_matches('/'),
222	        token
223	    ))
224	}
