258	// ─────────────────────────────────────────────────────────────────────────────
259	// Tiny crypto helpers (dependency-light hex + sha256 + url-safe base64).
260	// ─────────────────────────────────────────────────────────────────────────────
261	
262	fn random_url_token() -> String {
263	    let mut bytes = [0u8; TOKEN_BYTES];
264	    rand::thread_rng().fill_bytes(&mut bytes);
265	    base64_url_encode(&bytes)
266	}
267	
268	pub(crate) fn sha256_hex(input: &[u8]) -> String {
269	    let mut h = Sha256::new();
270	    h.update(input);
271	    hex_encode(&h.finalize())
272	}
273	
274	fn hex_encode(bytes: &[u8]) -> String {
275	    let mut s = String::with_capacity(bytes.len() * 2);
276	    for b in bytes {
277	        s.push_str(&format!("{b:02x}"));
278	    }
279	    s
280	}
281	
282	fn hex_decode(s: &str) -> Option<Vec<u8>> {
283	    if !s.len().is_multiple_of(2) {
284	        return None;
285	    }
286	    let mut out = Vec::with_capacity(s.len() / 2);
287	    let mut chars = s.chars();
288	    while let (Some(a), Some(b)) = (chars.next(), chars.next()) {
289	        let h = a.to_digit(16)?;
290	        let l = b.to_digit(16)?;
291	        out.push(((h << 4) | l) as u8);
292	    }
293	    Some(out)
294	}
295	
296	fn base64_url_encode(bytes: &[u8]) -> String {
297	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
298	    URL_SAFE_NO_PAD.encode(bytes)
299	}
