1	//! Per-IP rate limiter for auth endpoints.
2	//!
3	//! Sliding-minute counter, capped at 10 hits per IP per minute and 100
4	//! per hour. Implementation is intentionally tiny — DashMap of
5	//! `(ip, endpoint) -> RateWindow`. Stale entries are pruned on every
6	//! 50th insert; we don't bother with a background task.
7	//!
8	//! On limit exceeded we return 429 with no body — leaking whether the
9	//! email/token was valid would defeat the purpose of rate limiting.
10	//!
11	//! The `ip` this keys on must come from [`crate::ClientIp`] — the TCP peer,
12	//! consulting `x-forwarded-for` only from a declared trusted proxy. Deriving
13	//! it from headers is what made the limiter bypassable (#76 S5-4); there is
14	//! deliberately no header-reading helper in this module to reach for.
15	
16	use std::sync::atomic::{AtomicU64, Ordering};
17	
18	use crate::error::{ConsoleApiError, ConsoleResult};
19	use crate::state::{ConsoleState, RateWindow};
20	use crate::time::now_epoch_ms;
21	
22	const PER_MINUTE: u32 = 10;
23	const PER_HOUR: u32 = 100;
24	const WINDOW_MIN_MS: i64 = 60_000;
25	const WINDOW_HOUR_MS: i64 = 3_600_000;
26	
27	/// Counter of insertions, used to drive periodic pruning so we never
28	/// pay for a full sweep. (DashMap iter is per-shard locking, so a
29	/// 1-in-50 prune keeps tail latency unaffected.)
30	static INSERT_COUNTER: AtomicU64 = AtomicU64::new(0);
31	
32	/// Charge one hit against the `(ip, endpoint)` bucket. Returns `Ok(())`
33	/// if under the limits, `Err(RateLimited)` otherwise.
34	pub fn charge(state: &ConsoleState, ip: &str, endpoint: &str) -> ConsoleResult<()> {
35	    let now_ms = now_epoch_ms();
36	
37	    // Per-minute key
38	    let key_min = format!("{ip}:{endpoint}:m");
39	    let win = state
40	        .auth_rate_counters
41	        .entry(key_min.clone())
42	        .or_insert(RateWindow {
43	            count: 0,
44	            window_start_ms: now_ms,
45	        });
46	    let mut win_val = *win;
47	    drop(win); // release the entry guard so we can reinsert
48	
49	    if now_ms - win_val.window_start_ms > WINDOW_MIN_MS {
50	        win_val = RateWindow {
51	            count: 0,
52	            window_start_ms: now_ms,
53	        };
54	    }
55	    win_val.count += 1;
56	    if win_val.count > PER_MINUTE {
57	        return Err(ConsoleApiError::RateLimited);
58	    }
59	    state.auth_rate_counters.insert(key_min, win_val);
60	
61	    // Per-hour key
62	    let key_hour = format!("{ip}:{endpoint}:h");
63	    let win = state
64	        .auth_rate_counters
65	        .entry(key_hour.clone())
66	        .or_insert(RateWindow {
67	            count: 0,
68	            window_start_ms: now_ms,
69	        });
70	    let mut win_val = *win;
71	    drop(win);
72	
73	    if now_ms - win_val.window_start_ms > WINDOW_HOUR_MS {
74	        win_val = RateWindow {
75	            count: 0,
76	            window_start_ms: now_ms,
77	        };
78	    }
79	    win_val.count += 1;
80	    if win_val.count > PER_HOUR {
81	        return Err(ConsoleApiError::RateLimited);
82	    }
83	    state.auth_rate_counters.insert(key_hour, win_val);
84	
85	    if INSERT_COUNTER
86	        .fetch_add(1, Ordering::Relaxed)
87	        .is_multiple_of(50)
88	    {
89	        prune(state, now_ms);
90	    }
91	    Ok(())
92	}
93	
94	fn prune(state: &ConsoleState, now_ms: i64) {
95	    state
96	        .auth_rate_counters
97	        .retain(|_k, v| now_ms - v.window_start_ms < WINDOW_HOUR_MS);
98	}
