1	//! Magic-link issue + redemption.
2	//!
3	//! `POST /auth/magic/issue   { email, role }`
4	//!
5	//! An owner or admin mints a single-use invite link for `email`. If no
6	//! user with that email exists yet a `pending` row is provisioned so the
7	//! invitee flips to `active` once they enrol a passkey. The raw token is
8	//! returned exactly once; only its `sha256` is persisted.
9	//!
10	//! `POST /auth/magic/redeem  { token }`
11	//!
12	//! Looks up `sha256(token)` in `.xerj_magic_links`, validates expiry
13	//! and single-use, marks `used_at = now`, and returns an enrollment
14	//! session id the SPA echoes back on `POST /auth/passkey/begin`.
15	//!
16	//! Enrollment session lives only in RAM (not persisted) for 30 minutes
17	//! and is consumed exactly once by `passkey/finish`.
18	
19	use axum::{extract::State, response::Response, Json};
20	use rand::RngCore;
21	use serde::{Deserialize, Serialize};
22	use serde_json::json;
23	
24	use crate::auth::{audit, rate_limit, store, AuthSession};
25	use crate::bootstrap::sha256_hex;
26	use crate::client_ip::ClientIp;
27	use crate::error::{ConsoleApiError, ConsoleResult};
28	use crate::indices;
29	use crate::response::ok;
30	use crate::state::{ConsoleState, EnrollmentSession};
31	use crate::time::{now_epoch_ms, now_iso, parse_iso};
32	
33	const ENROLL_TTL_MS: i64 = 30 * 60 * 1000;
34	/// How long an admin-issued invite link stays valid before it must be
35	/// re-minted. Invites travel out-of-band (email/chat) so they get a much
36	/// longer window than the in-session enrollment handoff.
37	const INVITE_TTL_MS: i64 = 72 * 60 * 60 * 1000; // 72 hours
38	/// Roles an operator is allowed to grant when issuing an invite. Anything
39	/// outside this set is rejected rather than written verbatim into a user
40	/// row, so a typo can't mint an unrecognised (and therefore unchecked)
41	/// privilege string.
42	const INVITE_ROLES: &[&str] = &["owner", "admin", "editor", "viewer"];
43	
44	// ─────────────────────────────────────────────────────────────────────────────
45	// Issue (admin-only invite minting)
46	// ─────────────────────────────────────────────────────────────────────────────
47	
48	#[derive(Debug, Deserialize)]
49	pub struct IssueBody {
50	    pub email: String,
51	    pub role: String,
52	}
53	
54	#[derive(Debug, Serialize)]
55	pub struct IssueResponse {
56	    /// The raw token — returned exactly once. Only its `sha256` is stored,
57	    /// so this is the operator's single chance to hand it to the invitee.
58	    pub token: String,
59	    /// Host-relative setup link the operator can forward; the origin is
60	    /// supplied by whatever server rendered the console.
61	    pub link: String,
62	    pub user_id: String,
63	    pub email: String,
64	    pub role: String,
65	    pub purpose: String,
66	    pub expires_at: String,
67	}
68	
69	/// `POST /auth/magic/issue { email, role }` — an owner or admin mints a
70	/// single-use invite link for `email`. When no user with that email exists
71	/// we provision a `pending` row so the invitee flips to `active` the moment
72	/// they redeem the link and enrol a passkey (`redeem` → `passkey/finish`).
73	pub async fn issue(
74	    State(state): State<ConsoleState>,
75	    session: AuthSession,
76	    ClientIp(ip): ClientIp,
77	    Json(body): Json<IssueBody>,
78	) -> ConsoleResult<Response> {
79	    // Only owners and admins may invite.
80	    match session.user.role.as_str() {
81	        "owner" | "admin" => {}
82	        _ => {
83	            return Err(ConsoleApiError::Forbidden(
84	                "only an owner or admin may issue invites".into(),
85	            ));
86	        }
87	    }
88	
89	    let email = body.email.trim().to_ascii_lowercase();
90	    if email.is_empty() || !email.contains('@') {
91	        return Err(ConsoleApiError::BadRequest(
92	            "a valid email is required".into(),
93	        ));
94	    }
95	    let role = body.role.trim();
96	    if !INVITE_ROLES.contains(&role) {
97	        return Err(ConsoleApiError::BadRequest(format!("unknown role: {role}")));
98	    }
99	    // Privilege ceiling: only an owner may grant the owner role, so an admin
100	    // can't quietly mint a peer with more authority than themselves.
101	    if role == "owner" && session.user.role != "owner" {
102	        return Err(ConsoleApiError::Forbidden(
103	            "only an owner may invite another owner".into(),
104	        ));
105	    }
106	
107	    // Provision or look up the invitee. Re-inviting an existing address reuses
108	    // that row (and its current role) rather than duplicating the user or
109	    // silently escalating them via the invite.
110	    let now = now_iso();
111	    let user = match store::find_user_by_email(&state.engine, &email).await? {
112	        Some(u) => u,
113	        None => {
114	            let u = store::User {
115	                id: uuid::Uuid::new_v4().to_string(),
116	                email: email.clone(),
117	                display_name: String::new(),
118	                role: role.to_string(),
119	                status: store::UserStatus::Pending,
120	                created_at: now.clone(),
121	                last_seen_at: None,
122	            };
123	            store::upsert_user(&state.engine, &u).await?;
124	            u
125	        }
126	    };
127	    let user_id = user.id;
128	
129	    // Mint a random 32-byte URL-safe token; persist only its sha256.
130	    let mut token_bytes = [0u8; 32];
131	    rand::thread_rng().fill_bytes(&mut token_bytes);
132	    let token = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(token_bytes);
133	    let token_hash = sha256_hex(token.as_bytes());
134	
135	    let now_ms = now_epoch_ms();
136	    let expires_at = crate::time::epoch_ms_to_iso(now_ms + INVITE_TTL_MS);
137	
138	    let link = store::MagicLink {
139	        id: token_hash.clone(),
140	        purpose: "invite".to_string(),
141	        user_id: Some(user_id.clone()),
142	        email: Some(email.clone()),
143	        role: role.to_string(),
144	        created_by: session.user.id.clone(),
145	        created_at: now,
146	        expires_at: expires_at.clone(),
147	        used_at: None,
148	    };
149	    store::put_magic_link(&state.engine, &link).await?;
150	
151	    audit::record(
152	        &state.engine,
153	        &session.user.id,
154	        "magic-issued",
155	        indices::MAGIC_LINKS,
156	        Some(&token_hash),
157	        Some(&ip),
158	        Some(json!({ "purpose": "invite", "invitee": user_id.clone(), "role": role })),
159	    )
160	    .await;
161	
162	    let setup_link = format!("/_xerj-console/setup#token={token}");
163	    Ok(ok(
164	        IssueResponse {
165	            token,
166	            link: setup_link,
167	            user_id,
168	            email,
169	            role: role.to_string(),
170	            purpose: "invite".to_string(),
171	            expires_at,
172	        },
173	        None,
174	    ))
175	}
176	
177	// ─────────────────────────────────────────────────────────────────────────────
178	// Redeem
179	// ─────────────────────────────────────────────────────────────────────────────
180	
181	#[derive(Debug, Deserialize)]
182	pub struct RedeemBody {
183	    pub token: String,
184	}
185	
186	#[derive(Debug, Serialize)]
187	pub struct RedeemResponse {
188	    pub enrollment_session_id: String,
189	    pub email: Option<String>,
190	    pub role: String,
191	    pub expires_at: String,
192	}
193	
194	pub async fn redeem(
195	    State(state): State<ConsoleState>,
196	    ClientIp(ip): ClientIp,
197	    Json(body): Json<RedeemBody>,
198	) -> ConsoleResult<Response> {
199	    // Rate-limit by source IP. `ClientIp` resolves that from the TCP peer,
200	    // consulting `x-forwarded-for` only when the peer is a configured
201	    // trusted proxy (#76 S5-4) — this endpoint is unauthenticated, so a
202	    // header-derived key would let anyone mint a fresh quota per request.
203	    rate_limit::charge(&state, &ip, "magic-redeem")?;
204	
205	    if body.token.is_empty() {
206	        return Err(ConsoleApiError::BadRequest("missing token".into()));
207	    }
208	    let token_hash = sha256_hex(body.token.as_bytes());
209	
210	    // #76 S5-3: serialize the single-use check and the mark-used commit. The
211	    // used-check (below) and `mark_magic_link_used` (get→delete→create) are
212	    // separated by several awaits with no exclusive lock, so two concurrent
213	    // redeems of one token could both pass the check and both mint a session.
214	    // Hold the gate for the rest of this function so check→consume is atomic.
215	    // `lock_owned` avoids tying the guard's lifetime to `state` across awaits.
216	    let _redeem_guard = state.redeem_gate.clone().lock_owned().await;
217	
218	    // Look it up.
219	    let link = store::get_magic_link(&state.engine, &token_hash)
220	        .await?
221	        .ok_or_else(|| {
222	            // Single error message regardless of "doesn't exist" vs
223	            // "expired" vs "used" — never leak which one.
224	            audit_redeem_failed(&state, "not-found", &ip);
225	            ConsoleApiError::Unauthorized("invalid or expired link".into())
226	        })?;
227	
228	    // Single-use.
229	    if link.used_at.is_some() {
230	        audit_redeem_failed(&state, "already-used", &ip);
231	        return Err(ConsoleApiError::Unauthorized(
232	            "invalid or expired link".into(),
233	        ));
234	    }
235	    // Expiry.
236	    if let Some(exp) = parse_iso(&link.expires_at) {
237	        if now_epoch_ms() > exp.timestamp_millis() {
238	            audit_redeem_failed(&state, "expired", &ip);
239	            return Err(ConsoleApiError::Unauthorized(
240	                "invalid or expired link".into(),
241	            ));
242	        }
243	    }
244	
245	    // Resolve target user. Bootstrap links have no user_id yet — we
246	    // synthesise one. Invite links carry the user_id we already
247	    // provisioned in pending state.
248	    let (user_id, email) =
249	        match link.purpose.as_str() {
250	            "bootstrap" => {
251	                // Make sure no active user has snuck in between mint and
252	                // redeem (race window when two operators open the same
253	                // banner).
254	                let active = store::count_active_users(&state.engine).await?;
255	                if active > 0 {
256	                    audit_redeem_failed(&state, "bootstrap-already-claimed", &ip);
257	                    return Err(ConsoleApiError::Conflict(
258	                        "this server has already been claimed; ask your admin for an invite".into(),
259	                    ));
260	                }
