120	pub async fn finish(
121	    State(state): State<ConsoleState>,
122	    ClientIp(ip): ClientIp,
123	    headers: HeaderMap,
124	    Json(body): Json<FinishBody>,
125	) -> ConsoleResult<Response> {
126	    rate_limit::charge(&state, &ip, "login-finish")?;
127	
128	    let pending = state
129	        .pending_challenges
130	        .remove(&body.challenge_id)
131	        .map(|(_, v)| v)
132	        .ok_or_else(|| ConsoleApiError::Unauthorized("unknown challenge".into()))?;
133	    let auth_state = match pending.kind {
134	        ChallengeKind::Login { state: s, .. } => s,
135	        _ => return Err(ConsoleApiError::Unauthorized("wrong challenge kind".into())),
136	    };
137	
138	    let webauthn = webauthn_setup::build(&state)?;
139	    let auth_result: AuthenticationResult = webauthn
140	        .finish_passkey_authentication(&body.credential, &auth_state)
141	        .map_err(|e| {
142	            tracing::debug!(error = %e, "passkey authentication failed");
143	            ConsoleApiError::Unauthorized("authentication failed".into())
144	        })?;
145	
146	    // Look up the credential we just authenticated, then the user.
147	    let cred_id_b64 = base64::engine::general_purpose::URL_SAFE_NO_PAD
148	        .encode::<&[u8]>(auth_result.cred_id().as_ref());
149	    let pk = match get_passkey_by_id(&state, &cred_id_b64).await? {
150	        Some(p) => p,
151	        None => {
152	            // Should be impossible given the challenge state used the
153	            // same credential set, but stay defensive.
154	            return Err(ConsoleApiError::Unauthorized(
155	                "authentication failed".into(),
156	            ));
157	        }
158	    };
159	
160	    let user = store::get_user(&state.engine, &pk.user_id)
161	        .await?
162	        .ok_or_else(|| ConsoleApiError::Unauthorized("user gone".into()))?;
163	    if user.status != store::UserStatus::Active {
164	        return Err(ConsoleApiError::Unauthorized("user disabled".into()));
165	    }
166	
167	    // Update last_used_at on the passkey + sign-count is handled inside
168	    // webauthn-rs's Passkey state which we re-serialise.
169	    let mut updated_pk = pk.clone();
170	    updated_pk.last_used_at = Some(now_iso());
171	    // Re-serialise the Passkey blob so any internal counter updates land.
172	    if let Ok(typed) = serde_json::from_value::<Passkey>(pk.blob.clone()) {
173	        updated_pk.blob = serde_json::to_value(&typed).unwrap_or(pk.blob);
174	    }
175	    store::put_passkey(&state.engine, &updated_pk).await?;
176	
177	    let ua = headers
178	        .get("user-agent")
179	        .and_then(|h| h.to_str().ok())
180	        .map(|s| s.to_string());
181	    let (_session, signed) =
182	        sessions::mint_session(&state, &user.id, "passkey", Some(ip.clone()), ua).await?;
183	
184	    audit::record(
185	        &state.engine,
186	        &user.id,
187	        "session-minted",
188	        indices::SESSIONS,
189	        None,
190	        Some(&ip),
191	        Some(json!({ "via": "login" })),
192	    )
193	    .await;
194	
195	    let cookie = sessions::make_set_cookie(signed, false);
196	    let body = ok(
197	        json!({
198	            "user": {
199	                "id":    user.id,
200	                "email": user.email,
201	                "role":  user.role,
202	            }
203	        }),
204	        None,
205	    );
206	    Ok((
207	        axum_extra::extract::cookie::CookieJar::new().add(cookie),
208	        body,
209	    )
210	        .into_response())
211	}
