166	pub async fn finish(
167	    State(state): State<ConsoleState>,
168	    ClientIp(ip): ClientIp,
169	    headers: HeaderMap,
170	    Json(body): Json<FinishBody>,
171	) -> ConsoleResult<Response> {
172	    // Pull and consume both the enrollment session and the challenge —
173	    // either error fails the request without a partial commit.
174	    let enroll = state
175	        .enrollment_sessions
176	        .remove(&body.enrollment_session_id)
177	        .map(|(_, v)| v)
178	        .ok_or_else(|| ConsoleApiError::Unauthorized("unknown enrollment session".into()))?;
179	    if now_epoch_ms() > enroll.expires_at_ms {
180	        return Err(ConsoleApiError::Unauthorized(
181	            "enrollment session expired".into(),
182	        ));
183	    }
184	
185	    let pending = state
186	        .pending_challenges
187	        .remove(&body.challenge_id)
188	        .map(|(_, v)| v)
189	        .ok_or_else(|| ConsoleApiError::Unauthorized("unknown challenge".into()))?;
190	    let reg_state = match pending.kind {
191	        ChallengeKind::PasskeyEnroll { user_id, state } if user_id == enroll.user_id => state,
192	        _ => {
193	            return Err(ConsoleApiError::Unauthorized(
194	                "challenge does not belong to this enrollment".into(),
195	            ))
196	        }
197	    };
198	
199	    let webauthn = webauthn_setup::build(&state)?;
200	    let passkey: Passkey = webauthn
201	        .finish_passkey_registration(&body.credential, &reg_state)
202	        .map_err(|e| ConsoleApiError::Unauthorized(format!("attestation rejected: {e}")))?;
203	
204	    // Persist the credential.
205	    let cred_id_bytes: &[u8] = passkey.cred_id().as_ref();
206	    let credential_id_b64 = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(cred_id_bytes);
207	    let pk_blob = serde_json::to_value(&passkey)?;
208	    let pk = store::StoredPasskey {
209	        id: credential_id_b64.clone(),
210	        user_id: enroll.user_id.clone(),
211	        name: body.name.unwrap_or_else(|| "default".into()),
212	        created_at: now_iso(),
213	        last_used_at: None,
214	        blob: pk_blob,
215	    };
216	    store::put_passkey(&state.engine, &pk).await?;
217	
218	    // Upsert the user — flip pending → active. Bootstrap claims also
219	    // land here (placeholder user gets its first concrete data here).
220	    let now = now_iso();
221	    let email = body
222	        .email
223	        .clone()
224	        .or_else(|| Some(enroll.email.clone()).filter(|s| !s.is_empty()))
225	        .unwrap_or_default();
226	    let display_name = body.display_name.clone().unwrap_or_else(|| email.clone());
227	
228	    let existing = store::get_user(&state.engine, &enroll.user_id).await?;
229	    let user = match existing {
230	        Some(mut u) => {
231	            u.email = email;
232	            u.display_name = display_name;
233	            u.status = store::UserStatus::Active;
234	            u.last_seen_at = Some(now.clone());
235	            u
236	        }
237	        None => store::User {
238	            id: enroll.user_id.clone(),
239	            email,
240	            display_name,
241	            role: enroll.role.clone(),
242	            status: store::UserStatus::Active,
243	            created_at: now.clone(),
244	            last_seen_at: Some(now.clone()),
245	        },
246	    };
247	    store::upsert_user(&state.engine, &user).await?;
248	
249	    // Audit + session cookie.
250	    let ua = headers
251	        .get("user-agent")
252	        .and_then(|h| h.to_str().ok())
253	        .map(|s| s.to_string());
254	
255	    audit::record(
256	        &state.engine,
257	        &user.id,
258	        "passkey-enrolled",
259	        indices::PASSKEYS,
260	        Some(&credential_id_b64),
261	        Some(&ip),
262	        None,
263	    )
264	    .await;
265	
266	    let (_session, signed) =
267	        sessions::mint_session(&state, &user.id, "passkey", Some(ip.clone()), ua).await?;
268	
269	    audit::record(
270	        &state.engine,
271	        &user.id,
272	        "session-minted",
273	        indices::SESSIONS,
274	        None,
275	        Some(&ip),
276	        Some(json!({ "via": "passkey-enroll" })),
277	    )
278	    .await;
279	
280	    let cookie = sessions::make_set_cookie(signed, false);
281	    let body = ok(
282	        json!({
283	            "user": {
284	                "id":   user.id,
285	                "email": user.email,
286	                "role":  user.role,
287	            },
288	            "passkey": {
289	                "id":   pk.id,
290	                "name": pk.name,
291	            }
292	        }),
293	        None,
294	    );
295	    Ok((
296	        axum_extra::extract::cookie::CookieJar::new().add(cookie),
297	        body,
298	    )
299	        .into_response())
