54	pub async fn begin(
55	    State(state): State<ConsoleState>,
56	    Json(body): Json<BeginBody>,
57	) -> ConsoleResult<Response> {
58	    // Look up the enrollment session.
59	    let enroll = state
60	        .enrollment_sessions
61	        .get(&body.enrollment_session_id)
62	        .map(|e| e.clone())
63	        .ok_or_else(|| ConsoleApiError::Unauthorized("unknown enrollment session".into()))?;
64	
65	    if now_epoch_ms() > enroll.expires_at_ms {
66	        state
67	            .enrollment_sessions
68	            .remove(&body.enrollment_session_id);
69	        return Err(ConsoleApiError::Unauthorized(
70	            "enrollment session expired".into(),
71	        ));
72	    }
73	
74	    // Email: prefer the body (operator may be entering it for the first
75	    // time on a bootstrap claim) and fall back to whatever was on the
76	    // magic link.
77	    let email = body
78	        .email
79	        .clone()
80	        .or_else(|| Some(enroll.email.clone()).filter(|s| !s.is_empty()))
81	        .unwrap_or_default();
82	    if email.is_empty() {
83	        return Err(ConsoleApiError::BadRequest(
84	            "email is required to enrol the first credential".into(),
85	        ));
86	    }
87	
88	    // Email-uniqueness check: a different user with this email already
89	    // exists. Skip when this is the same user we're enrolling for
90	    // (re-running begin is fine).
91	    if let Some(existing) = store::find_user_by_email(&state.engine, &email).await? {
92	        if existing.id != enroll.user_id {
93	            return Err(ConsoleApiError::Conflict(format!(
94	                "email {email} is already registered"
95	            )));
96	        }
97	    }
98	
99	    // Existing credentials to exclude (avoids a single physical key
100	    // being enrolled twice for the same user).
101	    let exclude: Vec<CredentialID> = store::list_passkeys_for_user(&state.engine, &enroll.user_id)
102	        .await?
103	        .into_iter()
104	        .filter_map(|p| {
105	            let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
106	                .decode(&p.id)
107	                .ok()?;
108	            Some(CredentialID::from(bytes))
109	        })
110	        .collect();
111	
112	    let webauthn = webauthn_setup::build(&state)?;
113	    let user_unique_id = uuid::Uuid::parse_str(&enroll.user_id).unwrap_or_else(|_| Uuid::new_v4()); // synthetic placeholders are uuids; legacy ids fall back.
114	
115	    let display_name = body.display_name.clone().unwrap_or_else(|| email.clone());
116	    let (creation_options, reg_state) = webauthn
117	        .start_passkey_registration(
118	            user_unique_id,
119	            &email,
120	            &display_name,
121	            if exclude.is_empty() {
122	                None
123	            } else {
124	                Some(exclude)
125	            },
126	        )
127	        .map_err(|e| ConsoleApiError::Internal(format!("start registration: {e}")))?;
128	
129	    // Stash the registration state so /finish can verify the response.
130	    let challenge_id = random_id();
131	    state.pending_challenges.insert(
132	        challenge_id.clone(),
133	        PendingChallenge {
134	            kind: ChallengeKind::PasskeyEnroll {
135	                user_id: enroll.user_id.clone(),
136	                state: reg_state,
137	            },
138	            created_at_ms: now_epoch_ms(),
139	        },
140	    );
141	    prune_pending(&state);
142	
143	    Ok(ok(
144	        BeginResponse {
145	            challenge_id,
146	            creation_options,
147	        },
148	        None,
149	    ))

