169	pub async fn list(State(state): State<ConsoleState>, sess: AuthSession) -> ConsoleResult<Response> {
170	    let idx = state.engine.get_index(indices::DASHBOARDS)?;
171	    // Pull everything; filter by owner / visibility in code. The
172	    // `.xerj_dashboards` index is small (≤ low thousands) so the
173	    // simpler approach beats fighting bool-query semantics in tests.
174	    let body = json!({
175	        "query": { "match_all": {} },
176	        "size": 1000
177	    });
178	    let req = xerj_query::parser::parse_request(&body)
179	        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
180	    let r = idx.search(&req).await?;
181	
182	    let me = sess.user.id.as_str();
183	    let mut items: Vec<Value> = Vec::with_capacity(r.hits.len());
184	    for h in r.hits {
185	        let d: Dashboard = match serde_json::from_value(h.source) {
186	            Ok(d) => d,
187	            Err(_) => continue,
188	        };
189	        if d.deleted_at.is_some() {
190	            continue;
191	        }
192	        let visible = d.owner == me || d.visibility == "shared" || d.visibility == "default";
193	        if visible {
194	            items.push(serde_json::to_value(&d)?);
195	        }
196	    }
197	    Ok(ok(
198	        json!({ "dashboards": items, "total": items.len() }),
199	        None,
200	    ))
201	}
