    throw new Error(`safe-dom: <input type="${a.type}"> is not allowed`);
  }
  if (tag === 'button') {
    if (a.type && !BUTTON_TYPES.has(a.type)) throw new Error(`safe-dom: <button type="${a.type}"> is not allowed`);
