  const push = (x) => {
    if (x == null || x === false || x === true || x === '') return;
    if (Array.isArray(x)) { x.forEach(push); return; }
    if (isNode(x)) { c.push(x); return; }
    c.push(String(x));
  };
  children.forEach(push);
  return { $: 'node', tag, attrs: a, children: c };
