 * `good: 'up' | 'down' | null` — which direction lights the accent.
 * If `good` is null, delta is always muted (neutral).
 */
export const Change = (pct, { good = 'up', unit = '%', fractionDigits = 1 } = {}) => {
  if (pct == null || Number.isNaN(pct)) return '';
  const up = pct >= 0;
  const arrow = up ? '▲' : '▼';
